local quests = WordHunterWoW_QuestDataByFlavor.classic.deDE
quests[266] = { title = "Nachforschungen im Gasthaus", description = "Hier habt Ihr Euer Buch zurück, und noch viel Glück bei Euren Nachforschungen.\n\nVielleicht wollt Ihr Eure Suche auf das Gasthaus ausweiten. Wenn die Person, die Ihr sucht, einige Zeit hier in der Stadt verbracht hat, dann hat sie dort vielleicht jemand gesehen.", objectives = "Sucht im Gasthaus nach Hinweisen auf die schattenhafte Gestalt.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[267] = { title = "Die Bedrohung durch die Troggs", description = "$C, Ihr seid Euch vielleicht nicht unbedingt der Bedrohung durch die Troggs bewusst, die ihren Schatten über das Land der Zwerge wirft. Nachdem die Reserve von Ironforge zur Front der Allianz gerufen wurde, bleibt uns nur ein Bruchteil der Verteidigungskräfte, die nötig wären, um dieses Land zu schützen. Meinem Regiment wurde aufgetragen, über das Tor hier zu wachen, und wir können unseren Posten aufgrund der Gefahr einer Invasion nicht verlassen.\n\nEs muss aber etwas Druck auf diese verdammten Troggs ausgeübt werden, die in den Hügeln lauern. Wenn Ihr Euch dem gewachsen fühlt, startet einen Angriff auf die Troggs. Bringt mir 8 Trogg-Steinzähne als Beweis.", objectives = "Bringt Captain Rugelfuss im südlichen Wachturm 8 Trogg-Steinzähne.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[268] = { title = "Rückkehr zu Sven", description = "Das Buch, das Ihr gefunden habt, war nur zur Hälfte fertig geschrieben. Ich musste es auf Svens Hof zurücklassen, als ich hierher floh... \n\nHier. Nehmt mein vollständiges Tagebuch und bringt es zu Sven. Es beschreibt wesentlich genauer, was auf seinem Hof passierte.\n\nObwohl dieses Tagebuch in den letzten Wochen meine einzige Gesellschaft war, gebe ich es gern auf, wenn ich mir dadurch erspare, Sven und seiner Wut zu begegnen.", objectives = "Kehrt mit Jitters' vollständigem Tagebuch zu Sven zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[269] = { title = "Auf der Suche nach Weisheit", description = "Geht nach Stormwind und sprecht dort mit Bischof Farthing in der Kathedrale des Lichts. Gebt ihm Jitters' Tagebuch und sagt ihm, dass Ihr vorhabt, Euch Morbent Fel zu stellen.\n\nAuch wenn Stormwind Dunkelhain aufgegeben hat, ist Farthing doch eine gute Seele und sehr weise. Er könnte Euch bei Eurem Versuch, uns zu retten, behilflich sein.\n\nEure Mission ist gefahrvoll, aber beeilt Euch dennoch, $N. Mit jeder verstreichenden Stunde verfinstern sich die Schatten über dem Dämmerwald mehr und mehr.", objectives = "Gebt Bischof Farthing in Stormwind Jitters' vollständiges Tagebuch.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[270] = { title = "Die Verlorene Flotte", description = "Vor vielen Jahren sank die dritte Flotte von Kul'Tiras vor der Küste des Sumpflandes, einem Moorgebiet nördlich des Zwergenkönigreichs von Ironforge. Auf einem der Schiffe befand sich eine Ladung Lichtgeschmiedetes Eisen.\n\nDieses Metall ist wertvoll für uns, da Gegenstände, die daraus gefertigt werden, mit heiliger Wahrheit zuschlagen. Wenn Ihr Morbent Fel entgegentreten wollt, dann werdet Ihr eine solche Waffe brauchen.\n\nGeht zum Hafen von Menethil und sprecht mit meinem zwergischen Kollegen Glorin Steelbrow. Wenn dieses verlorene Metall überhaupt gefunden werden kann, dann weiß er, wo man danach suchen muss.", objectives = "Geht zum Hafen von Menethil im Sumpfland und sprecht mit Glorin Steelbrow.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[271] = { title = "Vyrins Rache", description = "Ihr seid nicht zufällig daran interessiert, es unserem ach so kühnen Kühnen ein wenig heimzuzahlen? Es schmerzt mich, das zu sagen, aber Daryl hat ein gewisses Talent.\n\nVor einem Jahr war ein großer Bär das Ziel der Weitschreiter-Lodge, aber keiner der Jäger hatte Glück mit ihm. Also dachte sich Daryl, er könnte sich mal an ihm versuchen. Das einzige, was er nach seinem Versuch vorweisen konnte, war die hässliche Narbe über seinem Auge.\n\nErlegt den Bären und ich bin mir sicher, dass sogar Daryl mal sprachlos wäre.\n\nDer Bär, Old Sooty, hält sich irgendwo in der Nähe seines Baus in den Hügeln über Thelsamar auf.", objectives = "Tötet Old Sooty und zeigt Daryl dem Jüngling in der Weitschreiter-Lodge dann Euer Werk.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[272] = { title = "Prüfung des Seelöwen", description = "Für die zweite Prüfung benötigt Ihr die zwei Hälften, aus denen der Anhänger des Seelöwen besteht. Die eine Hälfte bezieht ihre Kraft aus der Beweglichkeit des Seelöwen-Aspektes beim Gleiten durchs Wasser; die andere Hälfte bezieht ihre Kraft aus der unglaublichen Ausdauer des Seelöwen-Aspektes. Druiden bedienen sich dieser beiden Eigenschaften gleichermaßen, um den Aspekt ihrer Wassergestalt zu verkörpern.\n\nSprecht mit den Bewohnern von Moonglade, um herauszufinden, wo sich die Teile befinden könnten, und bringt beide hierher, um sie miteinander zu vereinen. Bringt den Anhänger zu Dendrite Starblaze, wenn Ihr ihn geschaffen habt.", objectives = "Sucht die Anhängerhälfte der Wasserbeweglichkeit und die Anhängerhälfte der Wasserausdauer. Sprecht mit den Einwohnern von Moonglade, um Hinweise darauf zu erhalten, wo sich diese Gegenstände befinden könnten.\n\nFormt den Anhänger des Seelöwen aus den beiden Anhängerhälften. Ihr müsst in der unmittelbaren Nähe des Schreins von Remulos sein, um dies zu tun.\n\nBringt den zusammengefügten Anhänger zu Dendrite Starblaze nach Nighthaven in Moonglade.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[273] = { title = "Nachschub für die Ausgrabungsstätte", description = "Es ist noch nicht zu spät, Ihr könnt gern losziehen und Huldar suchen. Er kann noch nicht sehr weit gekommen sein, denn so stark sie auch sein mögen, können Miran und Saean dennoch nicht allzu schnell laufen, wenn sie mit diesen Fässern vollgepackt sind.\n\nSie nehmen die übliche Route zur Ausgrabungsstätte, südwärts aus der Stadt raus und dann an der Krümmung des Lochs entlang.\n\nIhr solltet keine Probleme haben, sie zu finden, solange sie nicht bereits dort angekommen sind.", objectives = "Sprecht mit Huldar.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[274] = { title = "Eine dunkle Bedrohung", description = "Dies ist kein gewöhnliches Sprengpulver. Seht diese winzigen Silberkristalle. Und der eindeutige Geruch! Es ist sonnenklar, dass es sich hier um Zephyriumpulver handelt. Zephyrium an sich ist harmlos. Aber wenn es nass wird, könnte es ganz Ironforge aus dem Berg sprengen.\n\nDie chemische Reaktion kann entschärft werden, indem man vier Komponenten mischt: Lauerergift, einen zerstoßenen Kristall der Mo'grosh, eine Krokiliskenträne und diese Entschärfungspaste. Jetzt geht und erklärt es Hinderweir, ehe es zu spät ist!", objectives = "Ashlan Stonesmirk möchte, dass Ihr zum Chefingenieur Hinderweir zurückkehrt und ihn von der neuen Entdeckung in Kenntnis setzt.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[275] = { title = "Schwärendes Land", description = "Ich weiß nicht warum, aber irgendetwas schwärt im Sumpfland. Moorkrabbler haben sich dort ausgebreitet. Sie sind wie kranke, fiebrige Blasen auf dem Land, und um das Fieber zu besiegen, müssen sie erledigt und dem Sumpf wieder zugeführt werden.\n\nDie Moorkrabbler watscheln mitten in den Wasserwegen des Sumpflandes herum.", objectives = "Tötet 12 Moorkrabbler und kehrt dann zu Rethiel dem Sumpfhüter im Sumpfland zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[276] = { title = "Stapfende Pfoten", description = "Die Moosfellgnolle lebten viele Jahre friedlich im Sumpfland, aber in letzter Zeit wächst ihre Anzahl. Ihre Füße trampeln die Büsche und Blumen des Moores platt, und ihre garstigen Äxte schlagen zu viel Holz für ihre Feuer.\n\nSie befinden sich nicht mehr im Gleichgewicht mit dem Land. Wenn das Sumpfland überleben soll, müssen die Gnolle dezimiert werden.\n\nTötet 15 Gnolle der Moosfelle und 10 Bastarde der Moosfelle. Jagt sie im Süden, nahe dem Zwergentor von Algaz. Wenn Ihr das getan habt, kehrt zu mir zurück.", objectives = "Tötet 15 Gnolle der Moosfelle sowie 10 Bastarde der Moosfelle und kehrt dann zu Rethiel dem Sumpfhüter im Sumpfland zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[277] = { title = "Feuer-Tabu", description = "Die Moosfelle fällen die Bäume des Sumpflandes und verwenden das Fleisch der Bäume, um sich mit Feuer zu wärmen. Ich werde diesen Schmerz nicht länger ertragen!\n\nEntledigt die Moosfelle ihrer kunstlosen Feuersteine, der Werkzeuge, die sie zum Feuermachen verwenden. Die meisten Moosfelle tragen diese Feuersteine bei sich, ausgenommen die kleineren Gnolle der Moosfelle und Bastarde der Moosfelle.", objectives = "Bringt Rethiel dem Sumpfhüter 9 kunstlose Feuersteine.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[278] = { title = "Eine dunkle Bedrohung", description = "Fangt gleich damit an, die Stoffe zum Entschärfen zusammenzusuchen, $N. Lauerergift kann von den im Loch Modan heimischen Spinnen gewonnen werden. Krokiliskentränen findet man ebenfalls hier im Loch. Ein Kristall der Mo'grosh hingegen dürfte sehr schwierig zu bekommen sein. Die Oger im Nordosten bauen sie ab, aber die Kristalle sind ein sehr seltener Rohstoff.\n\nWir müssen einen Angriff der Dunkeleisenzwerge abwehren können! Kommt zurück, wenn Ihr alle erforderlichen Dinge zusammenhabt, und ich werde die Mixtur vorbereiten.", objectives = "Chefingenieur Hinderweir möchte, dass Ihr Lauerergift, einen Kristall der Mo'grosh und eine Krokiliskenträne besorgt.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[279] = { title = "Klauen aus der Tiefe", description = "Murlocs kriechen aus den tiefen Wassern und bauen ihre Dörfer entlang der Küste. Sie überfallen unsere Fischer und Händler und müssen aufgehalten werden.\n\nEiner dieser Murlocs, Gobbler, streift mit den anderen Murlocs der Blaukiemen umher und plündert die Händler entlang der Straße aus, wobei sie sich danach immer in die Sicherheit der nahegelegenen Hütten zurückziehen. Unsere Händler sind in Gefahr, und wir sind bereit, für ihre Sicherheit zu zahlen.\n\nGobbler strolcht in der kleinen Bucht nördlich von hier herum. Findet ihn, erschlagt seine Artgenossen und bringt mir seinen Kopf.", objectives = "Tötet 12 Murlocs der Blaukiemen.\n\nErschlagt Gobbler und nehmt Euch seinen Kopf.\n\nBringt Gobblers Kopf zu Karl Boran in den Hafen von Menethil", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[280] = { title = "Eine dunkle Bedrohung", description = "Heute habe ich einige Aufrührer der Dunkeleisenzwerge gesehen, die mit einem Fässchen in Richtung Damm geschwommen sind. Es waren keine Gebirgsjäger zur Hand, um sie aufzuhalten! Ich fürchte, sie haben das Zephyrium am Fuße des Dammes deponiert, und es könnte jede Minute hochgehen! Lasst mich diese ganzen Zutaten zur Entschärfungsmixtur zusammenmischen. Na bitte!\n\nIhr müsst jetzt diese Mixtur mitnehmen und in das Fässchen einrühren, bevor es zu spät ist! Beeilt Euch!", objectives = "Chefingenieur Hinderweir will, dass Ihr zum Fuß des Dammes hinunterschwimmt, das Pulverfässchen ausfindig macht und die Entschärfungsmixtur hineinrührt, um eine Explosion zu verhindern.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[281] = { title = "Waren-Wiederbeschaffung", description = "Vor nicht allzu langer Zeit wurde ein Handelsschiff, die Blind Princess, von Murlocs überfallen. Obwohl das Schiff unversehrt entkam, wurde ein Großteil seiner Fracht von den Kreaturen über Bord gezogen, darunter eine äußerst wertvolle Statuette von Terenas Menethil. Wir möchten, dass die Statuette geborgen wird.\n\nDurchsucht die Hütten der Murloc an der Küste nach Kisten, Fässern und anderen Spuren von verlorener Fracht. Findet die Menethil-Statuette und bringt sie mir wieder.", objectives = "Durchsucht die Kisten und Fässer in den Murloclagern an der Küste.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[282] = { title = "Senirs Beobachtungen", description = "Ich hatte ursprünglich vor, meinen Lehrling mit meinem Bericht zu meinem Bruder Senir zu schicken, aber ich würde mich viel besser fühlen, wenn er in etwas... verlässlicheren Händen wäre. Natürlich nur, wenn es Euch nichts ausmacht?\n\nHmm... Ihr müsstet den Tunnel nehmen, um nach Kharanos zu gelangen.\n\nSprecht mit Gebirgsjäger Thalos, bevor Ihr durch den Tunnel geht. Er ist mittlerweile vollständig von den Troggs überrannt.\n\nFolgt der Straße zurück nach Anvilmar und geht dann weiter nach Osten zum Tunnel. Thalos ist ganz in seiner Nähe stationiert.", objectives = "Sprecht mit Gebirgsjäger Thalos.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[283] = { title = "Eine dunkle Bedrohung", description = "Das Fässchen zischt ein wenig.", objectives = "Die Entschärfungsmixtur scheint gewirkt zu haben. Kehrt zu Chefingenieur Hinderweir zurück und berichtet ihm die guten Neuigkeiten.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[284] = { title = "Die Suche geht weiter", description = "Ihr durchsucht gründlich diese Ansammlung von Murlochütten, findet aber keine Spur von der Menethil-Statuette.\n\nVielleicht gibt es in einer der beiden nahe gelegenen Hütten im Norden und Nordosten mehr Hinweise.", objectives = "Sucht nach der Menethil-Statuette.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[285] = { title = "Suche in weiteren Hütten", description = "Dieses Grüppchen Murlochütten offenbart auch nach einer gründlichen Überprüfung nichts.\n\n... Aber Ihr seid Euch sicher, dass der nächste Anhaltspunkt, den Ihr findet, nützlich sein wird.\n\nEine der Hütten nördlich von hier muss die Menethil-Statuette enthalten!", objectives = "Sucht weiter in den Hütten der Murlocs nach der Menethil-Statuette.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[286] = { title = "Rückgabe der Statuette", description = "Nachdem Ihr das Fass aus dem Dreck gezogen und geöffnet habt, findet Ihr eine in dünnes Stroh eingepackte, silbrige Figur. Sie stellt einen jungen, langhaarigen Paladin mit erhobenem Hammer dar.\n\nDies kann nur die Menethil-Statuette sein! Ihr müsst sie nun zu Karl Boran in den Hafen von Menethil zurückbringen.", objectives = "Bringt Karl Boran die Menethil-Statuette.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[287] = { title = "Höhle der Frostmane", description = "Ich bin mit meinem Bericht etwas im Rückstand und könnte Eure Hilfe brauchen, $n. Ich habe gerade herausgefunden, wo sich die Trolle verschanzt haben, aber ich habe so viele Trolle gesehen, dass ich mich nicht getraut habe, hineinzugehen.\n\nWas ich von Euch möchte, ist Folgendes: Geht runter zur Höhle, schaut Euch ein wenig darin um, tötet ein paar Trolle und kommt dann wieder hierher zurück.\n\nNehmt die Straße nach Norden, raus aus Kharanos. Sobald Ihr an der Brücke ankommt, folgt dem zugefrorenen Fluss westwärts, bis Ihr den Iceflowsee erreicht. Am linken Ufer werdet Ihr Brewnall vorfinden. Die Höhle liegt südwestlich des Dorfes.", objectives = "Erforscht die Höhle der Frostmane und tötet 5 Kopfjäger der Frostmane für Senir Whitebeard in Kharanos.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[288] = { title = "Die Dritte Flotte", description = "Ich war einst erster Maat auf der HERRIN DER MEERE, einem Linienschiff der dritten Flotte von Kul Tiras, der verlorenen Flotte. Verloren deshalb, weil die Flotte auf ihrer letzten Reise von roten Großdrachen angegriffen wurde. Großdrachen, die von Orcs beherrscht wurden!\n\nWir hatten keine Chance gegen das Drachenfeuer... und unsere Flotte ging just vor dieser Küste hier brennend unter. Ich bin der einzige Überlebende von diesen armen Schiffen.\n\n... Oh, mir brummt der Schädel! Ich werde einen frischen Drink brauchen, wenn ich mit diesem Kater klarkommen und meine Geschichte fortsetzen soll.", objectives = "Spendiert dem Ersten Maat Fitzsimmons einen Krug Met.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[289] = { title = "Die verfluchte Crew", description = "<Gestärkt setzt Fitzsimmons seine Geschichte fort...>\n\nIch bin der einzige Überlebende der unglückseligen Dritten Flotte von Kul Tiras, die vor der Küste im Norden vernichtet wurde. Aber obwohl ich das einzige Mitglied der Flotte bin, das noch atmet, bin ich nicht der einzige, der noch herumläuft! Denn auf einem unserer Schiffe war ein großer und schrecklicher Schatz versteckt, und dessen unheimliche Macht hält die Seelen meiner Brüder in den verrottenden Wracks gefangen.\n\nWenn Ihr allerdings einige meiner Brüder befreien könnt, könnt Ihr vielleicht auch den Fluch brechen, der auf ihnen lastet.", objectives = "Vernichtet 13 verfluchte Seeleute, 5 verfluchte Matrosen und den ersten Maat Snellig. Bringt Snelligs Schnupftabakdose zum ersten Maat Fitzsimmons im Hafen von Menethil.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[290] = { title = "Brechen des Fluchs", description = "Um den Fluch zu brechen und alle meine Brüder zu befreien, müsst Ihr das... Ding... das auf meinem Schiff verstaut ist, bergen und reinigen! Ich weiß nicht, was es war, aber ich weiß, dass es sicher in der Geldkassette des Schiffs verwahrt wurde, zu dem nur Kapitän Halyndor den Schlüssel hatte.\n\nMein alter Kapitän erscheint mir immer noch in meinen Träumen. Ich bin mir sicher, dass er auf meinem untergegangenen Schiff, der INTREPID, herumläuft. Besorgt Euch den Schlüssel von ihm und öffnet damit die Geldkassette der INTREPID.\n\nAnschließend, wenn Ihr das verfluchte Ding habt, bringt es zu Glorin Steelbrow, dem Priester, hier in der Stadt.", objectives = "Besorgt den Geldkassettenschlüssel der INTREPID von Kapitän Halyndor.\n\nVerwendet den Schlüssel, um die Geldkassette der INTREPID zu öffnen.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[291] = { title = "Die Berichte", description = "Wunderbar! Überbringt Senator Barin Redstone meinen Bericht. Er ist ein missmutiger Geselle, also stört Euch nicht an seinem wenig sonnigen Gemüt. Er ist in Ironforge, in der Halle, in der König Magni Hof hält.\n\nIhr kennt den Weg nach Ironforge nicht? Nehmt die Straße aus Kharanos heraus nach Norden, überquert die Brücke und folgt dann der Straße nach Osten den Berghang hinauf. Einige große Banner flankieren diese Straße.\n\nAch ja, und könntet Ihr es vielleicht vermeiden, zu erwähnen, dass Ihr mir geholfen habt? Ich kann die ja nicht glauben lassen, ich würde hier draußen nicht hart arbeiten, nicht wahr?", objectives = "Überbringt Senator Barin Redstone in Ironforge Senirs Bericht.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[292] = { title = "Das Auge von Paleth", description = "In der offenen Truhe erblickt Ihr eine geschwärzte Kugel, die in einem gruseligen Licht pulsiert. Dies ist der Schatz, von dem Fitzsimmons gesprochen hat: ein verfluchtes Auge von Paleth.\n\nBringt das verfluchte Auge von Paleth zum Zwergen-Priester Glorin Steelbrow im Hafen von Menethil. Fragt ihn, wie man den Fluch des Auges brechen kann.", objectives = "Bringt Glorin Steelbrow das verfluchte Auge von Paleth.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[293] = { title = "Die Reinigung des Auges", description = "Ich kann den Fluch nicht von dem Auge von Paleth nehmen. Die Augen wurden von Menschen-Priestern hergestellt, daher werdet Ihr nach Stormwind gehen müssen, um jemanden zu finden, der Euch helfen kann. Sprecht mit Erzbischof Benedictus. Er steht der Kathedrale des Lichts in Stormwind vor. Er kann helfen.\n\nDas hoffe ich jedenfalls, um euretwillen.", objectives = "Bringt Erzbischof Benedictus das verfluchte Auge von Paleth. Ihr findet Benedictus in der Kathedrale des Lichts, in der Stadt Stormwind.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[294] = { title = "Ormers Rache", description = "Die Lage ist ernst, soviel ist sicher. Als wir diese Knochen freigelegt haben, hat das die Raptoren angelockt. Diese dreckigen Bestien haben meine Brüder getötet und mich, Merrin und den armen Ausgrabungsleiter hier festgesetzt.\n\nHelft mit, das Sumpfland von diesen Raptoren zu säubern, $N. Scheckige Raptoren und Scheckige Kreischer befinden sich direkt westlich der Klippe hier. Tötet jeweils 10, wenn Ihr könnt.\n\nDas wäre ein guter Anfang für die Rache, die ich mir für sie ausgedacht habe.", objectives = "Ormer Ironbraid von der Whelgars Ausgrabungsstätte möchte, dass Ihr 10 scheckige Kreischer und 10 scheckige Raptoren tötet.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[295] = { title = "Ormers Rache", description = "Es ist an der Zeit, diese abscheulichen Raptoren ihren Blutdurst bereuen zu lassen. Gleich da unten gibt es Dutzende von scheckigen Sensenklauen- und Scharfzahnraptoren. Lasst diese scheußlichen Kreaturen bezahlen, indem Ihr 10 von jeder Sorte erschlagt.", objectives = "Ormer Ironbraid möchte, dass Ihr 10 scheckige Sensenklauen- und 10 scheckige Scharfzahnraptoren tötet und dann zu ihm zu Whelgars Ausgrabungsstätte zurückkommt.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[296] = { title = "Ormers Rache", description = "Während Ihr da unten wart, ist mir aufgefallen, dass eines der Biester aus der Menge herausstach. Es war größer und bedrohlicher. Ich könnte wetten, das ist derjenige, der die anderen hierher geführt hat und für die Störung der Ausgrabungsstätte verantwortlich ist.\n\nIch erbitte eine letzte Aufgabe von Euch, $n. Sorgt dafür, dass Sarlatan seine gerechte Strafe erhält. Und wenn man die Schwere seiner Verbrechen bedenkt, bedeutet Gerechtigkeit in diesem Falle den Tod! Bringt mir eine seiner Krallen als Beweis, dass er tot ist.", objectives = "Ormer Ironbraid von der Whelgars Ausgrabungsstätte möchte, dass Ihr Sarlatan tötet und mit einer seiner Krallen zu ihm zurückkehrt, sobald Ihr die Aufgabe erledigt habt.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[297] = { title = "Götzen sammeln", description = "Vor einer Weile, kurz bevor die Troggs in der Stätte auftauchten, hatten wir eine große Anzahl seltsame, verzierte Götzen gefunden. Leider hatten wir keine Gelegenheit, sie zu untersuchen, denn kurz nach ihrer Entdeckung haben uns die Troggs aus den Ruinen verjagt. Und diese Götzen haben eine seltsame Wirkung auf die Troggs. Sie verfallen dadurch in Raserei!\n\nBringt mir 8 Götzen - ich möchte sie studieren, und ich will sie nicht mehr in den Händen der Troggs sehen. Ihr könnt die Götzen bei den Troggs finden, die die Stätte heimsuchen.", objectives = "Bringt Magmar Fellhew 8 verzierte Steingötzen.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[298] = { title = "Bericht über den Fortschritt der Ausgrabungen", description = "Ich muss einen Fortschrittsbericht nach Thelsamar schicken - einen Fortschrittsbericht und eine Neufassung meiner Anfrage nach mehr Sprengpulver! Hier ist der Bericht. Bringt ihn Jern Hornhelm. Er ist unser örtlicher Kontaktmann in Thelsamar.\n\nKeine schwierige Aufgabe, aber sie muss erledigt werden.", objectives = "Bringt Ironbands Fortschrittsbericht zu Jern Hornhelm in Thelsamar.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[299] = { title = "Enthüllung der Vergangenheit", description = "Kurz vor der Invasion habe ich eine große Schrifttafel gefunden, die man den Goazstein nennt. Der übersetzte Text reißt an 4 Stellen ab. Der Text spricht von einem \"göttlichen Plan\" und einer \"schicksalhaften Prophezeiung\".\n\nIch fürchte, uns läuft die Zeit davon. Ich bin zu alt, um hinunterzugehen und diesen Bestien zu trotzen. Aber Ihr seid stark.\n\nDurchkämmt die Ausgrabungsstätte und sucht die 4 fehlenden Tafelfragmente: Ados, Modr, Golm und Neru. Sucht sie in alten Artefakten oder dort, wo das Erdreich locker ist. Bringt sie mir, auf dass ich damit beginnen kann, ihre Geheimnisse zu enträtseln!", objectives = "Ausgrabungsleiter Whelgar wünscht, dass Ihr die Ausgrabungsstätte nach den 4 fehlenden Tafel-Fragmenten durchkämmt, Ados, Modr, Golm und Neru.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[301] = { title = "Meldung in Ironforge", description = "Wir werden eine Bewilligung brauchen, um Ironband mehr Sprengpulver zu beschaffen. Ihr müsst seinen Bericht zum Hauptquartier der Forscherliga in Ironforge bringen.\n\nHier ist der Bericht. Gebt ihn Ausgrabungsleiter Stormpike und vergesst nicht, Euch zu ducken, nachdem Ihr ihn abgeliefert habt. Stormpike ist ein Hitzkopf, und es wird ihn nicht erfreuen, wenn er von Ironbands langsamem Vorankommen an der Ausgrabungsstätte hört.\n\nIhr findet Stormpike in der Versammlungshalle der Forscher.", objectives = "Bringt Ironbands Fortschrittsbericht zu Ausgrabungsleiter Stormpike.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[302] = { title = "Pulver für Ironband", description = "Wenn Ironband immer noch Sprengpulver braucht, dann, bei Magni, soll er es haben! Ich habe die Bewilligung bereits mit einem Boten nach Thelsamar zu Jern Hornhelm vorausgeschickt. Er wird das Pulver und andere Vorräte zum Transport zu Ironband bereitstellen.\n\nAch, und noch was: Ich will, dass Ihr persönlich dafür Sorge tragt, dass diese Pulverlieferung ihren Bestimmungsort erreicht. Die letzte kam nicht an, also haltet Euren Verstand wach und Eure Augen offen.", objectives = "Sprecht in Thelsamar mit Jern Hornhelm.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[303] = { title = "Der Dunkeleisenkrieg", description = "Der Krieg tobt daheim ebenso wie in der Fremde. Während mächtige Zwergenkrieger im Namen der Allianz in weit abgelegenen Gegenden ihr Leben lassen, fallen unsere eigenen Gebiete den bösen Taten der Dunkeleisenzwerge zum Opfer. Sie haben den Thandol-Übergang verwüstet. Dun Modr fiel kurz darauf.\n\nIhr müsst Kräfte sammeln und die Front zurückdrängen. Wenn Ihr 15 Dunkeleisenzwerge, 5 Tunnelgräber der Dunkeleisenzwerge, 5 Saboteure der Dunkeleisenzwerge und 5 Demolierer der Dunkeleisenzwerge töten könnt, dann kommen die Reserven vielleicht rechtzeitig, um den Vormarsch zu beenden.\n\nUnd jetzt beeilt Euch!", objectives = "Motley Garmason in Dun Modr möchte, dass Ihr 15 Dunkeleisenzwerge, 5 Tunnelgräber der Dunkeleisenzwerge, 5 Saboteure der Dunkeleisenzwerge und 5 Demolierer der Dunkeleisenzwerge tötet.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[304] = { title = "Eine grausige Aufgabe", description = "Viele meiner Soldaten fielen in der Schlacht von Dun Modr. Mein eigener Bruder kam um, als die Westbrücke über dem Thandol-Übergang zerstört wurde. Jawohl, die Dunkeleisenzwerge sind eine teuflische Brut. Soweit Roggo das in Erfahrung bringen konnte, ist der Anführer dieses Verbrecherpacks im Sumpfland ein Hexenmeister namens Balgaras der Niederträchtige. Er ist allerdings ein ziemlicher Feigling. Er kommandiert seine Soldaten herum, bleibt aber selbst im Hintergrund, jegliche Gefahr meidend.\n\nWenn Ihr diesen rückgratlosen Abschaum finden könnt, erschlagt ihn und bringt mir sein Ohr. Ich werde Euch dafür entlohnen, $C.", objectives = "Tötet Balgaras den Niederträchtigen und bringt Longbraid dem Grimmigen vor Dun Modr sein Ohr.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[305] = { title = "Auf der Suche nach dem Ausgrabungstrupp", description = "Wie schön, Ihr müsst der Späher sein, den Longbraid zu schicken versprach. Ihr könnt Euch nicht vorstellen, wie besorgt ich war.\n\nMeine Frau, Merrin, hat mir im letzten Monat jede Woche Briefe geschickt. Sie gehört zum Whelgar-Ausgrabungstrupp. Aber es sind fast zwei Wochen seit unserem letzten Briefwechsel vergangen. Irgendetwas ist bestimmt schief gelaufen!\n\nLongbraid versprach, dass er einen Späher schicken würde, der sich dort mal umsieht, wenn wir nicht bald etwas vom Trupp hören. Ich nehme mal an, dieser Späher seid Ihr, $N. Findet Merrin in der Ausgrabungsstätte im Osten!", objectives = "Tarrel Rockweaver möchte, dass Ihr zur Ausgrabungsstätte reist und dort Kontakt mit Merrin Rockweaver aufnehmt.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[306] = { title = "Auf der Suche nach dem Ausgrabungstrupp", description = "Es war grauenhaft! Wir hatten einige seltene Artefakte enthüllt und fingen an, welche von diesen großen Knochen zu finden.\n\nBevor wir wussten, wie uns geschah, überrannten diese scheckigen Raptoren die Ausgrabungsstätte. Viele ließen ihr Leben.\n\nOrmer hier rettete - ganz tapfer - den Ausgrabungsleiter und mich. Er verteidigte uns, während wir Schutz suchten. Jetzt sind wir gefangen. Und unsere harte Arbeit liegt in Trümmern.\n\nHier, nehmt diese Nachricht mit zurück zu meinem süßen Tarrel. Sie wird ihm die Situation klarmachen.", objectives = "Kehrt mit Merrins Nachricht zu Tarrel Rockweaver zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[307] = { title = "Schmutzige Pfoten", description = "Die Silberbachmine im Osten hat sich schon vor langer Zeit erschöpft. Sie wurde vom Bund der Bergarbeiter in ein Lagerhaus umgewandelt, aber jetzt sind dort Kobolde eingezogen und befingern mit ihren schmutzigen Pfoten gute zwergische Werkzeuge!\n\nWir werden dieses Ungeziefer noch früh genug ausmerzen, aber der Bund wünscht, dass jemand ihre Gerätschaften aus der Mine schafft, bevor wir Krieger da reinstürmen und was kaputtmachen. Das wird ein harter Abstieg – Ihr solltet vielleicht Unterstützung mitnehmen.\n\nDie Ausstattung wird in Kisten des Bergarbeiterbunds über die Mine verteilt aufbewahrt. Viel Glück.", objectives = "Geht zur Silberbachmine und sucht 4 Sätze Bergarbeiter-Ausstattung zusammen.\n\nKehrt dann zu Gebirgsjäger Stormpike zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[308] = { title = "Jarvens Ablenkung", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[309] = { title = "Beschützen der Fracht", description = "Bereit zum Aufbruch, $N?\n\nAls Erstes müssen wir dieses Pulver zu Ironband bringen. Für mich allein wäre es zu viel zu tragen und diese Gegend kann gefährlich werden - und wer weiß, was diese Dunkeleisenzwerge noch für mich bereithalten?\n\nIch werde mich viel besser fühlen, wenn Ihr mitkommt.", objectives = "Stellt sicher, dass sowohl Miran als auch seine Warenlieferung sicher an der Ausgrabungsstätte ankommen und setzt dann Ausgrabungsleiter Ironband davon in Kenntnis.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[310] = { title = "Bittere Rivalen", description = "Ich muss zugeben, diese Donnerbräus stellen ein paar gute Getränke her. Aber sie müssen noch lernen, dass ihres nicht das einzige ordentliche Gebräu ist! Vielleicht könnt Ihr mir helfen, ihnen diese Lehre zu erteilen...\n\nHier, nehmt dieses Fass mit Gerstenbräu. Schleicht Euch in den Keller der Brauerei Donnerbräu in Kharanos und vertauscht es mit einem ihrer Fässer Donnerbier. Dann werden wir ja sehen, ob ihre Kundschaft mein Gebräu lieber mag als ihres!\n\nAch ja, und falls die Fässer bewacht sein sollten, müsstet Ihr eventuell den Wächter irgendwie ablenken...", objectives = "Vertauscht im Keller der Brauerei Donnerbräu in Kharanos ein Fass Donnerbier mit einem Fass Gerstenbräu.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[311] = { title = "Rückkehr zu Marleth", description = "Nachdem Ihr ein Fass von Marleths Gerstenbräu im Keller der Brauerei Donnerbräu abgestellt habt, schnappt Ihr Euch zum Beweis ein Fass Donnerbier...", objectives = "Bringt Marleth Gerstenbräu in Brewnall das Fass mit Donnerbier.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[312] = { title = "Tundra MacGranns gestohlene Vorräte", description = "Ich hatte einen Monatsvorrat Trockenfleisch gesalzen und für die kalte Jahreszeit weggeschlossen. Weggeschlossen deshalb, damit die Bären nicht rankommen! Aber während ich unterwegs auf der Jagd war, hat sich diese Bestie, Eisbart der Alte, mit meinem Fleisch-Spind davongemacht. Er wird allerdings nicht durch das Thorium kommen. Ich wiederum werde verhungern, wenn ich mein Fleisch nicht wiederbekomme.\n\nIhr seht verstohlener aus als ich. Vielleicht könnt Ihr meinen Vorrat wiederbeschaffen? Ich würde es mit meinem steifen Bein niemals schnell genug in die Höhle hinein und wieder heraus schaffen.", objectives = "Holt Tundra MacGranns Trockenfleisch aus dem gestohlenen Fleisch-Spind in der Höhle von Eisbart dem Alten.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[313] = { title = "Der altgediente Bau", description = "Nicht jeder ist dazu geschaffen, eine Belagerungsmaschine zu fahren. Dazu braucht man eine eiserne Hand und Nerven aus Stahl... zum Glück besitze ich beides! Wie steht's mit Euch? Wie groß ist euer Talent? Wollt Ihr es mir nicht zeigen?\n\nWie auch immer... ich versuche gerade, meine Maschine, Trollplow, etwas gemütlicher zu machen. Wie wäre es, wenn Ihr mir einen Haufen Wendigomähnen aus dem altgedienten Bau westlich von Kharanos besorgt? Diese Mähnen könnten einen tollen Teppich für das Innendeck abgeben!", objectives = "Sammelt 8 Wendigomähnen und bringt sie Pilot Stonegear.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[314] = { title = "Die Herde beschützen", description = "Wir haben mitten in der Nacht die Schreie gehört. Heute morgen fehlten der Herde dann tatsächlich zwei Widder. Diese heimtückische Bestie, Vagash genannt, hat sich über unsere Existenzgrundlage hergemacht. Da der Großteil von König Magnis Armee irgendwo in weit entfernten Landen an der Seite der Allianz kämpft, ist niemand mehr da, der Vagash in Schach halten könnte.\n\nVielleicht seid Ihr tapfer genug, die Bestie aufzuspüren und zu erschlagen. Bringt mir einen Fangzahn der Bestie, und ich werde Euch belohnen. Vagash lauert direkt oberhalb der Ranch hier, aber seid gewarnt, die Bestie ist tödlich.", objectives = "Rudra Amberstill möchte, dass Ihr Vagash erschlagt und einen seiner Fangzähne zu ihr auf die Widder-Ranch bringt.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[315] = { title = "Das perfekte Starkbier", description = "Ich bin von einem Vorhaben besessen, dem Vorhaben, das perfekte Starkbier herzustellen. Ich weiß, dass ich es schaffen kann - das Brauen liegt mir im Blut. Ich muss nur das richtige Rezept finden...\n\nWeit oben in den Bergen im Osten bauen die Trolle der Frostmane eine Pflanze an, Schimmerkraut genannt. Sie verwenden sie in ihren seltsamen Stammesritualen. Wir Zwerge haben bisher keine wirkliche Verwendung dafür gefunden, aber sie hat einen einzigartigen Geschmack... und ich möchte damit in meinen Gebräuen herumexperimentieren.\n\nBesorgt mir etwas Schimmerkraut von den Sehern der Frostmane oder klaut es aus den Schimmerkrautkörben der Trolle.", objectives = "Bringt Rejold Gerstenbräu in Brewnall 6 Schimmerkräuter.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[317] = { title = "Vorräte für Jetsteam", description = "Ich bereite mich gerade darauf vor, eine Mission für die Belagerungsbrigade in Angriff zu nehmen. Sie wird ziemlich lange dauern, und ich muss Jetsteam mit Vorräten für einen ganzen Monat beladen. Könntet Ihr also nicht, während Steelgrill an meinem Panzer arbeitet, ein wenig für mich auf die Jagd gehen?\n\nIch werde ein paar Pelze als Bettzeug und etwas Eberfleisch zum Essen brauchen. Ihr könnt das Fleisch von Ebern und die Pelze von Bären erbeuten... Ihr findet beide in den Schneefeldern südlich des altgedienten Baus.", objectives = "Sammelt 4 Brocken Eberfleisch und 2 dicke Bärenfelle und liefert sie bei Pilot Bellowfiz in Steelgrills Depot ab.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[318] = { title = "Immerschimmer", description = "Rejold Gerstenbräu experimentiert mit seinen Gebräuen. Ein paar davon schmecken gut, einige schlecht, und einige... nun, einige hauen selbst den stärksten Zwerg um.\n\nEr lebt in Brewnall, westlich von Kharanos, und ich will Immerschimmer, eines seiner Getränke. Es wird mich warmhalten, während ich in der Kälte unterwegs bin.\n\nAußerdem brennt das gesegnete Zeug so heiß, dass ich es in Jetsteams Brennofen kippen kann, um einen Energieschub zu erzeugen! Diese nette Taktik hat mich schon aus mehr als einer haarigen Situation gerettet.", objectives = "Besorgt von Rejold Gerstenbräu in Brewnall ein Fässlein Immerschimmer.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[319] = { title = "Ein Gefallen für etwas Immerschimmer", description = "Ich habe ein Fässlein mit Immerschimmer zur Hand, aber... könnt Ihr mir einen Gefallen tun? Brewnall könnte ein wenig Hilfe gebrauchen gegen die wilden Tiere, die die nahegelegenen Schneefelder durchstreifen. Manchmal kommen sie sehr nah.\n\nWir haben keine Angst vor diesen Bären und Katzen und Ebern - kein Zwerg, der etwas auf sich hält, hätte das - aber wenn Ihr Euch für uns um diese Tiere kümmern könntet, hätten wir mehr Zeit für unser Handwerk und unsere Braukunst.", objectives = "Tötet 6 Eisklauenbären, 8 alte Klippeneber sowie 8 Schneeleoparden und kehrt dann zu Rejold Gerstenbräu nach Brewnall zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[320] = { title = "Rückkehr zu Bellowfiz", description = "Hier habt Ihr Euer Fässlein mit Immerschimmer, $n. Und wie gesagt, vielen Dank für die Jagd kürzlich.", objectives = "Gebt Pilot Bellowfiz in Steelgrills Depot das Fässlein mit Immerschimmer.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[321] = { title = "Lichtgeschmiedetes Eisen", description = "Diese Schiffswracks hier vor der Küste sind die verlorene dritte Flotte von Kul'Tiras, die während des letzten großen Krieges von roten Drachen verbrannt und versenkt wurde.\n\nDie Flotte stammte aus Lordaeron, bis auf ein Schiff, einen elfischen Zerstörer: die Flying Osprey. Es transportierte eine Ladung Lichtgeschmiedetes Eisen und schloss sich der dritten Flotte aus Sicherheitsgründen an. Welche Ironie, dass es von denselben Drachen versenkt wurde... \n\nGenug Geschichte. Die Flying Osprey liegt südlich vom Hafen von Menethil auf Grund. Wenn Ihr das Lichtgeschmiedetes Eisen darin finden könnt, bringt es zu mir.", objectives = "Durchsucht das Wrack der FLYING OSPREY im Sumpfland.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[322] = { title = "Gesegnete Waffe", description = "Im Zwergendistrikt von Stormwind gibt es einen zwergischen Waffenschmied, der Lichtgeschmiedetes Eisen verarbeiten kann. Er heißt Grimand Elmore.\n\nIch habe das von Euch gefundene Eisen in eine Kiste gepackt. Bringt sie zu Grimand und erzählt ihm Eure Geschichte. Ich bin mir sicher, er wird jemandem, der auf einem Kreuzzug wie dem Euren ist, gefällig sein und Euch eine Waffe schmieden - eine Waffe, vor der sich sogar Morbent Fel fürchten wird.", objectives = "Bringt Grimand Elmore in Stormwind die Kiste mit Lichtschmiedeblöcken.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[323] = { title = "Bewährungsprobe", description = "Morbent Fel ist ein Totenbeschwörer und ein Verbündeter der dunklen Reiter. Ich würde Euch ja erlauben, Euch der Macht von Morbent Fel entgegenzustellen, aber ich werde Euch erst gegen diese widerwärtige Satanskreatur kämpfen lassen, wenn ich Eure wahre Stärke kenne.\n\nIhr habt mir Eure Tapferkeit bereits bewiesen, aber wenn Ihr dem Totenbeschwörer wirklich trotzen wollt, dann beweist Euer Geschick zuerst an seinen Dienern.", objectives = "Vernichtet 15 Skeletträuber, 3 Skelettheiler sowie 3 Skelettwärter und kehrt danach zu Sven zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[324] = { title = "Die verlorenen Blöcke", description = "Nachdem Ihr den einzelnen Lichtschmiedeblock aus der voll gelaufenen Kiste genommen habt, ist Euch klar, dass die Murlocs wohl den Rest gestohlen haben. Jagt die Murlocräuber in der Nähe des Wracks der Flying Osprey, um an das verloren gegangene Lichtgeschmiedetes Eisen zu kommen.", objectives = "Sammelt 5 Lichtschmiedeblöcke und kehrt dann zu Glorin Steelbrow im Sumpfland zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[325] = { title = "Bewaffnet und bereit", description = "Hier ist die Waffe gegen die Satanskreatur, von der Ihr spracht. Ihr seid bestens vorbereitet, $N. Viel Glück, und ich freue mich schon darauf, von Eurer Ruhmestat zu hören!", objectives = "Bringt Morbents Bann zu Sven im Dämmerwald.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[328] = { title = "Der versteckte Schlüssel", description = "In den Berichten wird kein Wort über den Gefreiten Thorsen verloren, jedoch im Einband eines von Herods Geschäftsbüchern findet sich ein kleiner Messingschlüssel.\n\nUnd nach genauerem Studium seiner Notizen finden sich in den verschiedenen Dokumenten einige Verweise auf eine \"sichere Geldkassette\". Die Geldkassette befindet sich irgendwo innerhalb des Vorratslagers - des Höhlenkomplexes weiter hinten in Kurzens Truppenlager.\n\nWenn diese sichere Geldkassette gefunden wird und der kleine Messingschlüssel ihn öffnen kann, dann kann das Geheimnis um Thorsens Entdeckung vielleicht offenbart werden.", objectives = "Verwendet den kleinen Messingschlüssel, um Buchhalter Herods Geldkassette zu öffnen.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[329] = { title = "Der entlarvte Spion", description = "Unter den Wertgegenständen in der Geldkassette befindet sich eine schlammverschmierte, gekritzelte Notiz. Wenn sie auch kaum lesbar ist, so scheint es, als wäre es eine Abhandlung über den Gefreiten Thorsen. Sie beschreibt ausführlich seine Patrouillenrouten, mit wem er so spricht und wie er seine Zeit bei den Rebellen verbringt. Sie ist nur mit einem einzelnen Buchstaben unterschrieben: -M.\n\nDennoch muss, wer auch immer diese Notiz verfasst hat, stets in Thorsens Nähe gewesen sein. Wer auch immer diese Notiz verfasst hat, ist der Verräter im Rebellen-Lager.", objectives = "Bringt die schlammverschmierte Notiz zu Lieutenant Doren im Rebellen-Lager.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[330] = { title = "Patrouillen-Pläne", description = "Die Notiz, die Ihr mir gegeben habt, ist mit einem \"-M\" unterzeichnet... Ich weiß nicht, was das heißen könnte.\n\nAber... die Notiz sagt auch aus, dass diese Person letzte Woche die gleichen Patrouillenrouten wie Thorsen hatte. Also muss, wer auch immer mit Thorsen letzte Woche auf Patrouille war, der Verräter sein!\n\nGeht zu Corporal Sethman. Er kümmert sich um die Patrouillenpläne und wird Euch sagen können, wer mit Thorsen unterwegs war.", objectives = "Sprecht mit Corporal Sethman.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[331] = { title = "Meldung bei Doren", description = "Wollte Lieutenant Doren, dass Ihr Euch mit diesen Patrouillen-Informationen wieder bei ihm meldet?", objectives = "Sprecht mit Lieutenant Doren.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[332] = { title = "Weinladen-Werbung", description = "Wenn Ihr Euch mit irgendwem über Weine unterhaltet, werdet Ihr erfahren, dass wir Gallinas die besten Weine in ganz Stormwind verkaufen. Wir sind auch nicht weit weg, immer noch innerhalb des Handelsdistrikts entlang der herrlichen Kanäle der Stadt.\n\nHier, nehmt dieses Flugblatt. Bringt es meiner Schwester Suzetta in unseren Laden, und Ihr erhaltet eine Gratis-Flasche unseres berühmten Pinot Noir. Ihr werdet es nicht bereuen!", objectives = "Geht zum Weingut Gallina und gebt Suzetta Gallina den Wein-Gutschein, um eine kostenlose Flasche Wein zu erhalten.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[333] = { title = "Harlan braucht Nachschub", description = "Wir hatten hier in der letzten Zeit viel Betrieb. Es scheint so, als wollte wirklich jeder Rüstungen und robuste Kleidung kaufen. Als würden alle eine kalte, harte Jahreszeit erwarten... \n\nAber das sind alles Zukunftssorgen. Meine heutige Sorge ist eher, dass mir die gestrickten Kleidungsstücke ausgehen. Ich brauche eine weitere Fuhre von unserem Lieferanten.\n\nWenn Ihr diesen Auftrag zu Rema Schneider in die Schneiderei und Anpasserei am Kanal bringen könntet, währe ich Euch sehr dankbar.", objectives = "Geht zur Schneiderei und Anpasserei am Kanal und bringt Rema Schneider Harlan Bagleys Kleidungs-Auftrag.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[334] = { title = "Eine Lieferung für Thurman", description = "Mein Sohn Thurman ist Lehrling beim Konfektionsgeschäft Larson im Magierviertel. Er hatte es heute etwas eilig und vergaß seine Schere und Nadeln. Ich weiß, ein großer $C wie Ihr hat bestimmt wichtige Aufgaben zu erledigen, aber ohne sein Handwerkszeug kann er seine Lehrarbeiten nicht erledigen!\n\nBitte, $N. Könnt Ihr meinem Sohn sein Nähkästchen vorbeibringen? Das Konfektionsgeschäft Larson ist einer von zwei Kleiderläden im Magierviertel - es ist das, das etwas weiter drin liegt, ganz in der Nähe des Magierturms.", objectives = "Geht zum Konfektionsgeschäft Larson im Magierviertel von Stormwind und gebt Thurman Schneider sein Nähkästchen.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[335] = { title = "Ein nobles Bräu", description = "Lord Wishock sorgt im Oberhaus ganz schön für Unruhe. Er wurde auf unseren kleinen \"Betrieb\" hier unten aufmerksam gemacht und propagiert jetzt eine genaue Untersuchung. Ich habe einen Plan, um Wishock... zu beschäftigen... aber ich benötige Eure Hilfe. \n\nEs gibt eine Blume, die in Stalvans Garten in den Außenbezirken von Dunkelhain wächst. Diese kleine weiße Blume ist als Tilloaträne bekannt. Ich werde außerdem eine Bisamwurzel brauchen, die man nur am Fuße des Wasserfalls tief unter dem Stonewroughtdamm im Sumpfland findet.", objectives = "Zardeth Blackclaw möchte, dass Ihr ihm eine Tilloaträne aus Dunkelhain und eine Bisamwurzel aus dem Sumpfland bringt.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[336] = { title = "Ein nobles Bräu", description = "Lord Wishock hat, wie alle Menschen, seine Schwächen. Bei seiner handelt es sich um eine Vorliebe für alkoholische Getränke. Seine Scheinheiligkeit ist verblüffend. Dieser spießige Trottel verbringt seine Tage damit zu versuchen, unsere kleine \"Taverne\" schließen zu lassen, während er seine Nächte im Obergeschoss zubringt und dabei Rechnungen anschreiben lässt, die er niemals bezahlt. Na, mal sehen, wie Wishock dieses besondere Gebräu schmeckt, das ich für ihn vorbereitet habe: Blackclaw-Starkbier. Es haut ziemlich rein, $N.\n\nBringt es ihm und seht, wie es ihm schmeckt. Höchstwahrscheinlich treibt sich der alte Trottel in der Halle der Bittsteller herum.", objectives = "Bringt Lord Wishock in der Halle der Bittsteller das Blackclaw-Starkbier.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[337] = { title = "Ein altes Geschichtsbuch", description = "Obwohl der Einband dieses Buches von Kratzern überzogen und von Schmutz verkrustet ist, kann man auf dem Buchrücken noch immer die Worte \"Die Geschichte von Stormwind\" lesen. Wenn man das Buch aufmacht, kann man das Siegel der Bibliothek von Stormwind erkennen, das deutlich auf der ersten Seite prangt.\n\nEs sieht so aus, als hätte jemand dieses Buch ausgeliehen, aber nie zurückgegeben.", objectives = "Bringt das Buch: \"Die Geschichte von Stormwind\" in die Bibliothek von Stormwind zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[338] = { title = "Die Grünen Hügel des Schlingendorntals", description = "Meister Nesingwary wird furchtbar wütend sein, wenn er das herausfindet!\n\nEr vertraute mir das Manuskript für seinen Roman, \"Die Grünen Hügel des Schlingendorntals\", zum Korrekturlesen an. Es lief auch alles glatt, aber dann wehte ein großer Windstoß durch das Lager und hat die Seiten überall verteilt.\n\nIch konnte die meisten Seiten wieder zusammensuchen, aber viele sind noch über den halben Dschungel verstreut. Sammelt die Seiten, mit denen man die vier Kapitel vervollständigen kann.\n\nIch werde Euch helfen, sie zu ordnen. Bringt mir die Kapitel zurück, wenn Ihr alle vier beisammen habt.", objectives = "Sammelt die fehlenden Seiten des Manuskripts von \"Die Grünen Hügel des Schlingendorntals”. Wenn alle vier Kapitel vollständig sind, bringt sie zu Barnil zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[339] = { title = "Kapitel I", description = "Kapitel I war ziemlich fesselnd! Meister Nesingwary baut den Hintergrund der Geschichte auf und erwähnt seine Jagdgefährten, mich eingeschlossen! \n\nAber das tut gerade nichts zur Sache. Lasst mich mal sehen, welche Seiten noch fehlen. So wie es aussieht sind die Seiten 1, 4, 6 und 8 immer noch irgendwo da draußen im Dschungel!", objectives = "Bringt Barnil Stonepot die Seiten 1, 4, 6 und 8 von Nesingwarys \"Die Grünen Hügel des Schlingendorntals”, um Kapitel I zu vervollständigen.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[340] = { title = "Kapitel II", description = "Kapitel II war voll gestopft mit aufregenden Geschichten von der Panther- und Tigerjagd. Ich könnte mir dafür in den Hintern treten, dass ich die Seiten habe davonfliegen lassen. \n\n Es sieht aus, als hätte ich alle Seiten wiedergefunden, bis auf die Seiten 10, 11, 14 und 16.", objectives = "Bringt Barnil Stonepot die Seiten 10, 11, 14 und 16 von Nesingwarys \"Die Grünen Hügel des Schlingendorntals\", um Kapitel II zu vervollständigen.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[341] = { title = "Kapitel III", description = "Kapitel III gefiel mir am besten. Es erzählt von Sire Erlgadins und Lady Rouacks erstem Blattschuss mit einem Zwergen-Gewehr. Und am Ende von Kapitel III, Mann, solche eine Spannung! \n\nWenn ich das richtig sehe, brauchen wir noch die Seiten 18, 20, 21 und 24, um das Kapitel fertig zu stellen. Diese Seiten sind irgendwo da draußen...", objectives = "Bringt Barnil Stonepot die Seiten 18, 20, 21 und 24 von Nesingwarys \"Die Grünen Hügel des Schlingendorntals”, um Kapitel III zu vervollständigen.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[342] = { title = "Kapitel IV", description = "Ah, Kapitel IV; Das große Finale! Und was für ein Ende es war! \n\nUns fehlen nur drei Seiten aus diesem Kapitel. Wir brauchen die Seiten 25, 26 und 27, um Kapitel IV wieder zusammenzusetzen.", objectives = "Bringt Barnil Stonepot die Seiten 25, 26 und 27 von Nesingwarys \"Die Grünen Hügel des Schlingendorntals\", um Kapitel IV zu vervollständigen.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[343] = { title = "Reden über Kraft", description = "Ich werde eine Rede über die Kraft des Geistes halten, und ich würde dazu gern einige Auszüge aus einem bestimmten Buch über Metallurgie zitieren - \"Belastbarkeit von Eisen\". Eine Abschrift dieses Buches dürfte sich in der königlichen Bibliothek der Burg Stormwind finden. Könnt Ihr es für mich holen? Wenn dem so ist, dann mögen die Segnungen des Lichts mit Euch sein!\n\nDie königliche Bibliothek ist sehr groß, aber der oberste Bibliothekar, Milton Sheaf, kennt jedes Regal, als wäre es sein eigenes Kind. Sprecht mit ihm, und er wird Euch das Buch holen.", objectives = "Geht in die königliche Bibliothek der Feste von Stormwind und sprecht mit Milton Sheaf. Er kann das Buch über Metallurgie für Euch finden, das Bruder Kristoff für seine Rede benötigt.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[344] = { title = "Bruder Paxton", description = "Belastbarkeit von Eisen? Ja, ich kenne das Buch. Ziemlich gut, vor einigen Jahrzehnten von dem Zwergenminenarbeiter Margulf Blaggon geschrieben. Er verbrachte den Großteil seines Lebens tief in den Bergen von Khaz Modan, Erze schürfend. Kluger Kerl!\n\nAber wo war ich doch gleich? Ach ja, die \"Belastbarkeit von Eisen\"! Ich fürchte, das Buch wurde in die Abtei von Nordhain verlegt. Der Verwalter der Bibliothek der Abtei, Bruder Paxton, wollte eine Kopie des Buches für seine eigenen Regale anfertigen.\n\nDas war allerdings vor Monaten. Ich frage mich, warum er so lange dafür braucht...", objectives = "Sprecht mit Bruder Paxton in der Abtei von Nordhain.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[345] = { title = "Tinten-Zutaten", description = "Ich will meine Abschrift von \"Belastbarkeit von Eisen\" schon länger fertig stellen, aber... \n\nNun, ich stelle für die Bücher, die ich abschreibe, meine Tinte selbst her, versteht Ihr? Es handelt sich um mein eigenes Rezept. Sie verläuft nicht, sie schmiert nicht und sie trocknet sehr schnell. Dummerweise trocknet sie ein wenig zu schnell! Meine letzte Portion ist ausgetrocknet, bevor ich die Abschrift beenden konnte, und ich hatte bisher keine Gelegenheit, mehr Tinte herzustellen!\n\nUm mehr herzustellen, benötige ich Rethbaneisenerz aus dem Rotkammgebirge. Großknecht Oslow in Seenhain ist mein üblicher Lieferant.", objectives = "Sprecht mit Großknecht Oslow in Seenhain und fragt ihn nach Rethbaneisenerz.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[346] = { title = "Rückkehr zu Kristoff", description = "Nachdem ich jetzt mit der Abschrift fertig bin, könnt Ihr das Original von \"Belastbarkeit von Eisen\" haben. Ich danke Euch für Eure Geduld, und wenn Ihr Milton seht, bitte sagt ihm, die lange Verzögerung täte mir Leid.", objectives = "Kehrt zu Bruder Kristoff auf den Kathedralenplatz zurück. Gebt ihm das Buch: \"Belastbarkeit von Eisen\".", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[347] = { title = "Rethbanerz", description = "Rethbanerz wurde nach dem Mann benannt, der es als Erster entdeckt hat, Bart Rethban. Wenn es geschmolzen wird, ist es nicht so stark wie Eisen, aber sein Erz hat eine dunkle, glatte Farbe, die einige Schreiber in ihren Farbtinten verwenden. Man kann es in den Rethbanhöhlen nördlich von hier finden.\n\nWir haben normalerweise etwas davon auf Lager, aber wir sind zu sehr damit beschäftigt, uns auf Orcangriffe vorzubereiten, als dass wir welches sammeln könnten. Und nur so nebenbei... In den Rethbanhöhlen leben jetzt Rotkammgnolle und deren Zwangsarbeiter bauen das Erz selbst ab.\n\nWenn Ihr also welches benötigt, müsst Ihr es Euch selbst besorgen.", objectives = "Sammelt 5 Fuhren Rethbanerz und bringt sie Bruder Paxton in der Bibliothek von Nordhain.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[348] = { title = "Schlingendornfieber", description = "Krank... so... furchtbar k-k-krank... \n\n... habe mich mit Schlingendornfieber angesteckt... tödliches V-v-virus... \n\n... einziges Heilmittel... wäre... wäre es... das Herz von M-m-m-mokk dem Wilden zu essen... schwer zu fassendes, weißes Wildtier... \n\n... Hexendoktor Unbagwa... Einziger, der es b-b-beschwören kann...\n\n... sucht Unbagwa... versteckte Höhle am südlichen Kap...\n\n... schnell... sterbe... sterbe...", objectives = "Sucht Hexendoktor Unbagwa und lasst ihn Mokk den Wilden beschwören. Bringt das Herz von Mokk zu Fin Fizracket.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[349] = { title = "Schlingendornfieber", description = "Hallo, $N!\n\nSprich mit meinem Freund Hexendoktor Unbagwa.", objectives = "Sprecht mit Hexendoktor Unbagwa.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[350] = { title = "Auf einen alten Freund verlassen", description = "Marzon würde ein Mitglied der Defias kontaktieren und er hat Verbindungen zu Lescovar... \n\nDa van Cleef und Thredd tot sind, wäre es schwierig, einen Richtspruch gegen Lescovar zu erwirken, denn Eure Beweise sind wertlos ohne deren Zeugnis. Und dabei wird noch nicht einmal die Tatsache berücksichtigt, dass Lescovar ja ein Adliger ist und viele Beziehungen hat. Das stellt ihn gewissermaßen über das Gesetz.\n\nWir werden weitere Hilfe benötigen. Ich tu das nur äußerst ungern, aber ich kenne jemanden, der uns helfen wird. Ihr findet Trias im Handelsdistrikt der Stadt.", objectives = "Sprecht mit Elling Trias in Stormwind.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[351] = { title = "Findet OOX-17/TN!", description = "Ihr habt ein merkwürdiges Gerät aus Metall entdeckt, das die Form eines Eis hat. Als Ihr einen der Knöpfe berührt, erwacht das Ei zu Leben und verwandelt sich in eine Art Gnom-Roboter-Apparat! Aus dem Inneren des Roboteis erklingt eine rasselnde Stimme.\n\n\"Mein Name ist Oglethorpe und mein Leitroboter ist verloren gegangen! Ich würde Euch belohnen, wenn Ihr ihn aufspürt! Bringt dem Roboter bitte diesen Signalgeber. Hervorragend, jetzt habe ich die Koordinaten für Euch berechnet! Er ist in der Nähe der Klaffenden Schlucht in Tanaris abgestürzt!\"", objectives = "Bringt das Notsignal zum Leitroboter von Oglethorpe.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[353] = { title = "Stormpikes Lieferung", description = "Die Stormpikes sind ein geachteter Zwergenklan und bekannt für ihren feinen und kritischen Geschmack. Daher ist es nicht verwunderlich, dass Gringer Stormpike, ein Gebirgsjäger aus Ironforge, mich beauftragte, ihm eine Waffe zu schmieden.\n\nDie Waffe ist fertig, aber... Gebirgsjäger Stormpike ist weit weg, am fernen Loch Modan. Wenn Ihr ohnehin vorhabt, nordwärts zu reisen, könntet Ihr ihm dieses Päckchen überbringen?\n\nMeine letzte Nachricht von Gebirgsjäger Stormpike besagte, dass er im nördlichen Wachturm des Loch Modan stationiert ist.", objectives = "Bringt das Päckchen für Stormpike zu Gebirgsjäger Stormpike am Loch Modan.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[354] = { title = "Todesfälle in der Familie", description = "Die Familie Agamand war die wohlhabendste in Tirisfal. Ich habe früher in ihrer Mühle gearbeitet... vor der Seuche.\n\nAls die Geißel das erste Mal auftauchte, befestigten die Agamands ihre Heimstatt und überredeten ihre Angestellten zu bleiben und bei der Verteidigung zu helfen. Wir waren Narren, aber wir waren loyale Narren.\n\nDie Agamands haben uns in ihrem Stolz zum Untod verdammt. Und heute sind sie Diener der Geißel!\n\nDient den Verlassenen, indem Ihr die Agamands besiegt, die der Seuche zum Opfer fielen. Dient mir, indem Ihr mir ihre Überreste bringt.", objectives = "Bringt Coleman Farthing in Brill Gregors Überreste, Nissas Überreste und Thurmans Überreste.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[355] = { title = "Gespräch mit Sevren", description = "Ihr habt mir die Überreste der Agamands gegeben und meinen Rachedurst gestillt. Aber Agamands Mühlen sind eine Bedrohung für alle Verlassenen, nicht nur für mich.\n\nIch habe mit Magistrat Sevren über Eure Heldentaten gegen die Agamands geredet, und er wünscht, mit Euch zu sprechen.", objectives = "Sprecht mit Magistrat Sevren in Brill.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[356] = { title = "Patrouille zur Rückendeckung", description = "Die Verteidiger auf dem Bollwerk, die Tirisfal vor den Pestländern schützen, sind immer wachsam. Aber manchmal schafft es die Geißel, an ihnen vorbeizuschlüpfen.\n\nUnser Erfolg am Bollwerk hängt an einer Ein-Fronten-Schlacht - wir können keinen Angriff von hinten zulassen, und noch weniger können wir zulassen, dass die Versorgungslinie unserer Verteidiger unterbrochen wird.\n\nUnterstützt das Bollwerk. Patrouilliert ostwärts und erschlagt alle Untoten, die Ihr findet. Seid auf Balnirs Bauernhof im Osten besonders gründlich. Es hat sich zu einem Zufluchtsort für eindringende Untote entwickelt.", objectives = "Tötet 8 blutende Schrecken und 8 wandernde Geister und meldet Euch dann wieder bei Linnea in ihrem Lager.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[357] = { title = "Die Identität des Lichs", description = "Es gibt einen Lich, der auf einer Insel im Blendwassersee im Norden haust. Obwohl er ein Verlassener mit freiem Willen ist, glaubt er, dass alle anderen Untoten Sklaven der Geißel sind, und hetzt seine Diener auf jeden, der sich ihm nähert.\n\nAber da er ein Verlassener ist, wird die Königin ihn haben wollen. Und wenn er in der Totenbeschwörung bewandert ist, dann wäre sein Wissen... recht nützlich für uns.\n\nUm etwas über seine Identität und sein Können herauszufinden, muss ich mir sein Zauberbuch ansehen. Stehlt Euch in sein Lager, verschafft es Euch und kehrt dann zu mir zurück.", objectives = "Bringt das Zauberbuch des Lichs zu Bethor Iceshard in Undercity.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[358] = { title = "Grabräuber", description = "Die Massengräber südwestlich von Garrens Schlupfwinkel weiter im Norden wurden geschaffen, um der... eindrucksvollen... Anzahl Todesfälle gerecht zu werden, die Tirisfal erlitt, als die Seuche zum ersten Mal über uns kam. \n\nDen Toten in diesen Gräbern blieb der Untod bisher erspart, aber die Geißel schickt jetzt Moderfellgnolle, um die Leichen einzusammeln, um sie zur Verstärkung ihrer Armeen einzusetzen. Das können wir nicht zulassen!\n\nIhr habt zweierlei Aufgaben: Erschlagt die Moderfelle am Massengrab und in Garrens Schlupfwinkel und nehmt Euch von ihnen das Einbalsamierungssekret, das ihnen Leben verleiht.", objectives = "Tötet Grabräuber der Moderfelle und Bastarde der Moderfelle. \n\nBringt Magistrat Sevren in Brill 8 Einbalsamierungssekrete.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[359] = { title = "Verlassenen-Pflichten", description = "Ich brauche einen aktuellen Bericht von unserem Außenposten der Todeswache im Osten.\n\nIch muss wissen, ob mehr Streitkräfte der Geißel am Bollwerk vorbei und nach Tirisfal herein geschlichen sind. Unsere Wachsamkeit an der Grenze zu den Pestländern muss aufrechterhalten werden - wir können die Geißel hier nicht stärker Fuß fassen lassen!\n\nReist südwärts die Straße entlang und biegt an der Gabelung nach Osten zum Außenposten ab. Sprecht mit Todeswache Linnea. Sie hat die Informationen, die ich benötige.", objectives = "Sprecht mit Todeswache Linnea.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[360] = { title = "Rückkehr zum Magistrat", description = "Kehrt jetzt zu Magistrat Sevren mit den Informationen zurück, die ich euch gegeben habe. Er wird sie so schnell wie möglich haben wollen, also sputet Euch.\n\nUnd solltet Ihr unterwegs welche von der Geißel sehen, schaltet sie aus - wir können sie nicht unbehelligt durch unser Land spazieren lassen.", objectives = "Kehrt zu Magistrat Sevren nach Brill zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[361] = { title = "Ein nie zugestellter Brief", description = "Dies ist ein Brief, der von Thurman, dem ältesten Sohn von Gregor Agamand, geschrieben wurde. Er ist an Yvette Farthing adressiert, aber er scheint nicht bei ihr angekommen zu sein...", objectives = "Findet Yvette Farthing und bringt Ihr den Brief von Thurman Agamand.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[362] = { title = "Die Spuk-Mühle", description = "Devlin Agamand war der jüngere von zwei Söhnen der Familie Agamand und im Leben hätten sie unterschiedlicher nicht sein können. Thurman war groß und sanft, während sein jüngerer Bruder schwach und scharfzüngig war.\n\nAls Agamands Mühlen der Seuche anheim fielen, war ich nicht überrascht zu hören, dass Devlin ihr schnell erlag. Sein verrücktes Gebrabbel kann man heute noch nahe der Straße hören, die zu Agamands Mühlen führt.\n\nIch sammle die Überreste der Agamands und ich möchte den armen Devlin. Findet ihn, vernichtet ihn und bringt mir seine Knochen.", objectives = "Erschlagt Devlin Agamand und bringt Devlins Überreste zu Coleman Farthing nach Brill.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[363] = { title = "Unsanftes Erwachen", description = "Wurde auch Zeit, dass Ihr aufwacht. Wir wollten Euch gerade mit den anderen ins Feuer werfen, aber es sieht so aus, als hättet Ihr es geschafft.\n\nIch bin Mordo, der Verwalter der Deathknell-Gruft. Und Ihr seid kein Sklave des Lichkönigs mehr.\n\nSprecht mit Schattenpriester Sarvis in der Kapelle am Fuße des Hügels, er wird Euch mehr über das erzählen, was Ihr wissen müsst.", objectives = "Sprecht mit Schattenpriester Sarvis.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[364] = { title = "Die Hirnlosen", description = "Wir Verlassenen liegen im Krieg mit der Geißel, der Armee des Lichkönigs: durch Nekromantie erweckte Armeen von Untoten, grausige Bestien des Nordens und gepeinigte Schreckgespenster.\n\nDer nördliche Teil des Dorfes wurde von den Hirnlosen überrannt, und diese müssen vernichtet werden. Vernichtet sie, zeigt ihnen keine Gnade, auch wenn sie unsere früheren Brüder und Schwestern gewesen sein mögen. Die Gefallenen sind nichts als Sklaven des Lichkönigs.", objectives = "Schattenpriester Sarvis will, dass Ihr 8 hirnlose Zombies und 8 elende Zombies tötet.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[365] = { title = "Felder des Kummers", description = "Was haben wir denn hier? Ihr seht wie ein Neuling aus, $C. Wenn Ihr darauf hofft, Euch der Dunklen Fürstin zu beweisen, dann müsst Ihr die Gebräuche der Verlassenen erlernen.\n\nIm Westen werdet Ihr einen Hof vorfinden. Menschen suchen das Land heim wie Schimmel eine verrottende Leiche. Und um es noch schlimmer zu machen, patrouilliert ganz in der Nähe der Scharlachrote Kreuzzug von seinem Turm aus. Erteilt diesem Abschaum eine Lektion und stehlt 10 ihrer kostbaren Kürbisse.\n\nSobald Ihr 10 beisammen habt, bringt sie zu Apotheker Johaan nach Brill.", objectives = "Stehlt 10 Kürbisse vom Gehöft im Westen, direkt nördlich von Deathknell und bringt sie zu Apotheker Johann nach Brill.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[366] = { title = "Rückgabe des Buches", description = "Vor langer Zeit waren Gunther und ich, wie auch der jetzt der Geißel dienende Totenbeschörer Thule Rabenklaue, Freunde und Schüler beim Kirin Tor, einer Magiergesellschaft in Dalaran.\n\nGunther und ich fielen beide der Seuche anheim, aber ich dachte, er wäre entweder tot geblieben oder für die Armee des Lichkönigs erweckt worden. Es tut gut zu wissen, dass er frei ist.\n\nWir müssen ihn für uns gewinnen. Ich habe einen Zauber auf dieses Buch gelegt, der ihm, sobald er ihn sieht, zeigen wird, dass ich ebenfalls frei vom Einfluss des Lichkönigs bin. Ich hoffe, dass er sich uns anschließt, wenn er das erfährt.", objectives = "Bringt Gunthers Zauberbuch zu ihm auf die \"Gunthers Zufluchtsort\" genannte Insel zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[367] = { title = "Eine neue Seuche", description = "Lady Sylvanas hat sich an die königliche Apothekervereinigung gewandt. Die dunkle Fürstin glaubt, dass unser Wissen, gepaart mit der neuentdeckten Magie, der Schlüssel zu Arthas' Untergang sein wird. Sie hat uns aufgefordert, eine neue Seuche zusammenzubrauen, eine Seuche, tödlicher als jedes Leiden in ganz Azeroth. Diese neue Krankheit wird Arthas' Armee der Geißel ins Verderben stürzen.\n\nMeine Studien zeigen, dass das Blut von Bestien der Schlüssel sein könnte. Bringt mir 5 Phiolen Schattenhundblut, damit ich meine Theorie ausprobieren kann.", objectives = "Apotheker Johaan in der Stadt Brill möchte, dass Ihr 5 Phiolen Schattenhundblut sammelt.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[368] = { title = "Eine neue Seuche", description = "Während Ihr unterwegs wart und Proben für mich gesammelt habt, haben meine Experimente ergeben, dass noch weitere Reagenzien benötigt werden, wenn sich diese Krankheit ordentlich ausbreiten soll. Ein paar unglückliche Opfer zu vergiften, ist eine Kleinigkeit. Eine ganze Welt erkranken zu lassen, erweist sich als etwas komplizierter.\n\nIch werde 5 Finsterflossenschuppen von den Murlocs in der Umgebung brauchen. Ihr findet die Kreaturen entlang der Küste im Norden oder Westen von hier.", objectives = "Apotheker Johaan in der Stadt Brill benötigt 5 Finsterflossenschuppen von den Murlocs in Tirisfal.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[369] = { title = "Eine neue Seuche", description = "Während Ihr sammeln wart, habe ich einen alten Text in einem meiner Bücher entdeckt, der darauf hindeutet, dass eine uralte Seuche Tausende unschuldiger Opfer ausgelöscht hat. Man fand später heraus, dass der tödliche Erreger im Gift der Nachtweberspinnen erhalten blieb.\n\nBringt mir etwas Gift eines heimtückischen Nachtwebers, um dieses Experiment abzuschließen. Ich möchte sehen, ob das ansteckende Element des Giftes mit meinem neuen Gebräu harmoniert. Gerüchten zufolge leben die Spinnen im östlichen Tirisfal.", objectives = "Apotheker Johaan in der Stadt Brill möchte, dass Ihr ihm 4 Proben vom Gift eines heimtückischen Nachtwebers bringt.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[370] = { title = "Im Krieg mit dem Scharlachroten Kreuzzug", description = "Die strategischen Dokumente von Exekutor Arren enthalten alle Angaben, die wir brauchen, um die menschliche Plage aus den Ländern zu tilgen. Nach diesen Informationen hat der Scharlachrote Kreuzzug Captain Perrine mit einer Brigade dem verfallenen Turm südwestlich von Brill zugeteilt.\n\nTötet Perrine, sowie 3 Zeloten und 3 Missionare und erstattet mir dann Meldung.", objectives = "Exekutor Zygand in Brill möchte, dass Ihr Captain Perrine, 3 Scharlachrote Zeloten und 3 Scharlachrote Missionare tötet.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[371] = { title = "Krieg mit dem Scharlachroten Kreuzzug", description = "Wir befinden uns noch immer im Krieg, und der Scharlachrote Kreuzzug gewinnt an Stärke. Der Bericht, den mir Exekutor Arren schickte, zeigt auf, dass die Scharlachroten Kreuzzügler ihre Überfälle von dem verfallenen Turm im südöstlichen Tirisfal, nahe Balnirs Bauernhof, unter dem Kommando von Captain Vachon ausgeführt haben.\n\nTötet Vachon, zusammen mit 5 Scharlachroten Ordensmitgliedern. Das sollte sich als vernichtender Schlag für den Kreuzzug erweisen!", objectives = "Exekutor Zygand in Brill hat Euch damit beauftragt, Captain Vachon und 5 Scharlachrote Ordensmitglieder zu erschlagen.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[372] = { title = "Krieg mit dem Scharlachroten Kreuzzug", description = "Scharlachrote Kreuzzügler haben vom verfallenen Turm im nördlichen Tirisfal, hinter Faols Ruheplatz, Überfälle ausgeführt. Nach den Informationen, die wir haben, führt ein unbarmherziger Kommandant mit Namen Captain Melrache diese bösartige Truppe an.\n\nIch vertraue Euch eine besondere und gefahrvolle Mission an. Erschlagt Melrache und seine beiden Leibwachen im Namen der dunklen Fürstin.", objectives = "Exekutor Zygand in der Stadt Brill möchte, dass Ihr Captain Melrache und seine beiden Leibwachen ermordet.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[373] = { title = "Der nie verschickte Brief", description = "Als Ihr Edwin van Cleef durchsucht, findet Ihr unter anderem einen nie verschickten Brief. Er ist adressiert an \"Baros Alexston, Stadtarchitekt von Stormwind, Rathaus, Kathedralenplatz\".\n\nEr scheint erst vor kurzem geschrieben und versiegelt worden zu sein.", objectives = "Bringt den Brief nach Stormwind zum Stadtarchitekten Baros Alexston.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[374] = { title = "Beweise des Ablebens", description = "Exekutor Zygand sagt mir, dass Ihr Scharlachrote Kreuzzügler töten wart. In Tirisfal wimmelt es nur so von denen.\n\nVarimathras, Offizier der Dunklen Fürstin, kümmert sich persönlich darum, dass der Abschaum Azeroths, die Menschen, völlig ausgelöscht wird. Hier in Tirisfal stehen wir einer besonders lästigen Menschenbrut gegenüber: dem Scharlachroten Kreuzzug.\n\nBegebt Euch hinaus und führt eine Offensive gegen den Scharlachroten Kreuzzug, $C. Bringt mir 10 Scharlachrote Insignienringe zum Beweis Eurer Loyalität Varimathras und der Dunklen Fürstin gegenüber.", objectives = "Bringt Todeswache Burgess in Brill 10 Scharlachrote Insignienringe.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[375] = { title = "Die Kälte des Todes", description = "Es ist jetzt so kalt. Die Seuche des Untodes kriecht durch meine Adern wie eine eisige Schlange. Ich werde bald den Hirnlosen Zustand erreichen. Doch auch ein besiegeltes Schicksal wird mich nicht davon abhalten, unserer Dunklen Fürstin zu dienen. Als der Ruf ertönte, nähte ich Leichensäcke für die gefallenen Soldaten von Sylvanas' mächtiger Armee.\n\nJetzt zittern meine Hände vor lauter Kälte. Wenn Ihr mir fünf Nachtsaugerpelze und etwas groben Faden bringen würdet, könnte ich mir eine Decke nähen. Helft mir, $n, auf dass ich der Sache weiter dienen kann.", objectives = "Bringt Gretchen Dedmar in Brill fünf Nachtsaugerpelze und etwas groben Faden.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[376] = { title = "Die Verdammten", description = "Meine Pflichten umfassen, die verwundeten Krieger zu versorgen, Rüstung und Kleidung zu schneidern und Schattenpriester Sarvis in jeder erdenklichen Weise zu unterstützen.\n\nEs sieht so aus, als würdet Ihr ebenfalls in seine Dienste aufgenommen... wahrscheinlich um die Hirnlosen zu jagen, wie ich ihn kenne. Tja, wenn Ihr dabei in einem Stück bleiben wollt - und ich bezweifle nicht, dass Ihr das wollt -, dann kann ich Euch vielleicht helfen. Mir gehen die Tatzen und Flügel aus, und wenn Ihr mir einige davon bringt, besorge ich Euch eine Rüstung. Ihr werdet im Norden eine Menge Wölfe und Fledermäuse finden.", objectives = "Novize Elreth benötigt 6 Aasfressertatzen und 6 Nachtsaugerflügel.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[377] = { title = "Verbrechen und Strafe", description = "Als wäre die Vernachlässigung der Einwohner des Dämmerwalds nicht schlimm genug, nein, die jüngste Entscheidung des Oberhauses, Dextren Ward in Stormwind ins Gefängnis zu werfen, anstatt den Schurken - wie durch Lord Ebonlockes Urteil gefordert - zu enthaupten, ist ein Schlag ins Gesicht für den Rat von Dunkelhain.\n\nWard wurde dabei erwischt, wie er Leichen aus dem Friedhof an Morbent Fel verkaufte, ein Verbrechen, auf das der Tod steht. Und dennoch fordert Stormwind seine Gefangensetzung.\n\nErmordet Ward im Verlies von Stormwind - bringt mir seine Hand - und ich werde Euch belohnen.", objectives = "Ratsherr Millstipe von Dunkelhain will, dass Ihr ihm die Hand von Dextren Ward bringt.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[378] = { title = "Tief empfundener Zorn", description = "Ihr habt Eure Loyalität zu König Magni bewiesen, $C. Und Euer Hass auf den Dunkeleisenabschaum ist genau so groß wie mein eigener.\n\nEs gibt da eine Aufgabe, die ich selbst beenden möchte, aber ich bin durch meine Ehre verpflichtet, bei Longbraid zu bleiben. Jedoch hat Roggo Informationen gesammelt, die belegen, dass Kam Deepfury einer der Verschwörer beim Angriff auf den Thandol-Übergang war. Durch Deepfurys Pläne verlor Longbraid seine Sippe.\n\nDeepfury wird aus politischen Gründen im Verlies von Stormwind festgehalten. Ich will ihn tot sehen, $N. Für Longbraid! Bringt mir seinen Kopf!", objectives = "Motley Garmason in Dun Modr verlangt Kam Deepfurys Kopf.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[379] = { title = "Durstlöscher", description = "Ihr möchtet eine Kraftquelle. Da kann ich Euch helfen. Wisst Ihr, was ich möchte? Ich möchte etwas zu Trinken! Bringt mir fünf Wasserbeutel eines Wüstenläufers und ich werde Euch die 4711-FTZ geben.\n\nUnd jetzt... ratet einmal, wo Ihr solche Wasserbeutel finden könnt! Warum geht Ihr nicht zu einem der Wüstenläufernomaden östlich von hier und bittet ihn um einen? Lasst mich wissen, ob das klappt.", objectives = "Bringt Chefingenieur Bilgewhizzle in Gadgetzan 5 Wasserbeutel eines Wüstenläufers.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[380] = { title = "Nachtweber", description = "Eine unserer größten Schwierigkeiten besteht darin, die Rohstoffe zu besorgen, die wir zum Überleben brauchen. Gold war schon zu Hochzeiten der Macht der Allianz selten.\n\nEs gibt eine Goldmine im Nordwesten, die von Spinnen überrannt wurde. Wir brauchen das Gold dieser Mine, aber wir können es ja schlecht holen, während die Spinnen darin herumkrabbeln. Ich habe nicht viel Personal übrig für diese Aufgabe, also müssen wir sie Schritt für Schritt lösen.\n\nBegebt Euch dorthin und schaut mal, was Ihr für uns ausrichten könnt, $n.", objectives = "Exekutor Arren will, dass Ihr 10 junge Nachtweber und 8 Nachtweber tötet.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[381] = { title = "Der Scharlachrote Kreuzzug", description = "Ihr werdet erfreut sein zu hören, dass wir anscheinend Fortschritte in der Mine machen. Der Dank dafür gebührt zu einem nicht unerheblichen Maß Euren Bemühungen. Nun können wir uns anderen Belangen zuwenden.\n\nMeine Späher haben berichtet, dass eine Abteilung des Scharlachroten Kreuzzugs südöstlich von hier ein Lager errichtet. Der Scharlachrote Kreuzzug ist eine verabscheuungswürdige Organisation, die uns jagt, und sie wird nicht ruhen, ehe nicht alle Untoten - ganz gleich, ob Teil der Geißel des Lichkönigs oder nicht - vernichtet sind. Wir müssen ihnen zuvorkommen!\n\nSeid vorsichtig, denn der unheilige Eifer dieser Leute macht sie zu gefährlichen Gegnern.", objectives = "Bringt Exekutor Arren insgesamt 12 Scharlachrote Armbinden von Scharlachroten Konvertiten und Scharlachroten Initianden.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[382] = { title = "Der Rote Bote", description = "Berichte meiner Vorgesetzten in Brill weisen darauf hin, dass ein Agent des Scharlachroten Kreuzzugs vom Scharlachroten Kloster hierher nach Deathknell entsendet wurde. Nach diesen Berichten führt dieser Bote wichtige Informationen mit sich. Ich kann nicht mit Einzelheiten dienen, aber was auch immer es ist, wir müssen es haben!\n\nIhr seid die qualifizierteste Person, die ich darauf ansetzen kann, $n. Findet diesen Boten und bringt mir alle Informationen, die er bei sich trägt.", objectives = "Tötet Meven Korgal, den Boten, im Lager der Kreuzzügler und kehrt danach mit allen Informationen, die Ihr findet, zu Exekutor Arren zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[383] = { title = "Entscheidende Informationen", description = "Das muss zu meinem Vorgesetzten, Exekutor Zygand, nach Brill gebracht werden. Mit diesen Informationen können wir dem Scharlachroten Kreuzzug einen entscheidenden Schlag versetzen. Eure Dienste waren hier in Deathknell nützlich, aber ich benötige jemanden, der dies zu Zygand bringt, und ich denke, er wird angemessenere Arbeiten für Euch finden. \n\nNehmt die Straße nach Norden, hinaus aus Deathknell. Kurz nachdem Ihr nach Tirisfal hineinkommt, trefft Ihr auf eine Kreuzung. Nehmt die Abzweigung nach Osten und behaltet diese Richtung dann bei. Ihr werdet unterwegs am Coldhearth-Anwesen vorbeikommen.", objectives = "Bringt die Dokumente des Scharlachroten Kreuzzugs zu Exekutor Zygand nach Brill.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[384] = { title = "Eberrippchen in Biersauce", description = "Meine Tavernengäste mögen nichts so sehr wie meine Eberrippchen in Biersauce. Das einzige Problem dabei ist, dass der ortsansässige Fallensteller, der mich bisher mit den Zutaten versorgt hat, in die Armee des Königs eingetreten ist, um im Krieg an der Allianzfront zu helfen. \n\nVielleicht könnt Ihr mir helfen? Wenn Ihr mir sechs Klippeneberrippchen bringt und ein Rhapsody-Malzbier von der Taverne hier besorgt, bekommt Ihr das Familienrezept für meine berühmten Eberrippchen in Biersauce, und nicht zu vergessen natürlich eine Kostprobe! Das Geheimnis liegt im Malz!", objectives = "Ragnar Donnerbräu in Kharanos benötigt 6 Klippeneberrippchen und einen Krug Rhapsody-Malzbier.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[385] = { title = "Krokiliskenjagd", description = "So manchen Jäger zieht es an den Loch Modan, um unsere berühmten Kroks zu erlegen. Irgendein Händler sucht immer Krokiliskenhäute für seine Kleidungsstücke oder Rüstungen und es gibt auch einige Leute, denen ihr Fleisch mundet.\n\nWir handeln ein wenig damit, aber nicht wirklich viel, denn die Krokilisken sind wild und haben sich auf den Inseln im Loch verschanzt. Aber ich will Euch nicht davon abbringen, denn es ist ein unvergessliches Erlebnis, mit den Kiefern der Bestien zu ringen.\n\nAch ja, das eine Mal damals...", objectives = "Besorgt 5 Stücke Krokiliskenfleisch und 6 Krokiliskenhäute für Marek Ironheart in der Weitschreiter-Lodge.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[386] = { title = "Verbrechen lohnt sich nicht", description = "Targorr der Schreckliche diente als oberster Exekutor unter Gath'llzogg. Er ging grausam vor, selbst nach den Standards der dreckigen Orcs. Menschen, die tapfer gekämpft hatten, um das Königreich zu verteidigen, wurden nur zu seiner Belustigung gefoltert. Heute wird er im Verlies von Stormwind gefangen gehalten und wurde zum Tode verurteilt. Dennoch stimmt irgendetwas nicht. Einer dieser bürokratischen Adeligen hat seine Exekution ausgesetzt. Ich bin mir sicher, hier wird eine Schandtat geplant.\n\nMacht Targorr dem Schrecklichen ein Ende, $N. Reist zum Verlies und enthauptet ihn, bevor man uns überlistet.", objectives = "Bringt Wache Berton in Seenhain den Kopf von Targorr dem Schrecklichen.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[387] = { title = "Niederschlagung des Aufstandes", description = "Der Aufstand muss niedergeschlagen werden! Ich brauche Eure Hilfe. Wenn jemand mitbekommt, dass das Gefängnis überrannt wurde, verliere ich meinen Job! Solch übles Spiel habe ich noch nie erlebt. Aber was jetzt zählt ist, die Gefangenen zur Sicherheit Stormwinds niederzuringen.\n\nDie Strafe für Auflehnung lautet Tod. Tötet einige dieser Abweichler! Das sollte die Angelegenheit wieder unter Kontrolle bringen.", objectives = "Aufseher Thelwater aus Stormwind will, dass Ihr im Verlies 10 gefangene Defias, 8 eingekerkerte Defias und 8 Aufrührer der Defias tötet.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[388] = { title = "Die Farbe von Blut", description = "Verbitterung fließt wie ein kalter Fluss durch meine Adern. Mein Enkel, Mac, war so ein guter Junge. Gerade mal 14 Jahre alt. Als die Armee an die Front geschickt wurde, griff Mac zu den Waffen, um die Stadt zu verteidigen. Er war eine Wache im Verlies, wo diese elenden Defias eingesperrt sind. Mac wies ein paar der Gefangenen dafür zurecht, dass sie ihre Wolldecken zerrissen, um Schals daraus zu machen, die ein Symbol ihrer Bande darstellen. Dafür wurde Mac hinterhältig erstochen.\n\nIch will Rache. Bringt mir 10 ihrer kostbaren Wollkopftücher. Sie haben die Farbe von Blut.", objectives = "Nikova Raskol von Stormwind will, dass Ihr 10 rote Wollkopftücher für sie sammelt.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[389] = { title = "Bazil Thredd", description = "Van Cleef und ich waren beide Mitglieder der Steinmetzgilde. Unser Hauptprojekt war der Wiederaufbau Stormwinds nach dem Krieg.\n\nAls wir unsere Aufgabe erfüllt hatten, wurden wir betrogen. Die Adligen verweigerten uns die Bezahlung für unsere Arbeit. Einigen der älteren Steinmetze wurden Posten in der Regierung angeboten, aber van Cleef lehnte aus Loyalität zu den übrigen Steinmetzen ab. Er führte eine Revolte an und verließ, Rache schwörend, die Stadt.\n\nSein Helfer, Bazil Thredd, könnte vielleicht mehr über van Cleefs Pläne wissen. Er wird im Verlies gefangen gehalten.", objectives = "Sprecht mit Aufseher Thelwater im Verlies.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[391] = { title = "Aufstand im Verlies", description = "Lasst uns eine Sache klarstellen, $n: Ich traue Euch nicht. Aber wie die Sache im Moment aussieht, werdet Ihr ohnehin keinen Unterschied machen.\n\nAlso wird das folgendermaßen ablaufen: Geht da runter und redet mit Thredd. Wenn Ihr wirklich auf unserer Seite seid, dann eliminiert ihn und bringt mir seinen Kopf, wenn Ihr fertig seid. Und falls sich herausstellt, dass Ihr auf seiner Seite seid und nicht herauskommt... werdet Ihr zusammen mit dem Rest dieser Würmer sterben, wenn wir Euch finden.", objectives = "Tötet Bazil Thredd und bringt seinen Kopf mit zurück zu Aufseher Thelwater im Verlies.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[392] = { title = "Der seltsame Besucher", description = "In den ersten Jahren von Thredds Gefangenschaft bekam er niemals Besuch. Ich ging davon aus, dass er für die Bruderschaft keinen Nutzen mehr hatte und sie ihn daher fallen ließ.\n\nAber vor einigen Monaten hat sich das alles geändert; er bekam regelmäßig Besuch ... einmal, manchmal sogar zweimal pro Woche. Es war ein seltsamer Mann, so ein ruhiger Typ. Ich hatte da so meinen Verdacht, aber alle seine Papiere waren in Ordnung.\n\nLaut seinen Dokumenten war sein Name Maelik; hier habt Ihr seine Beschreibung. Ich glaube nicht, dass er noch einmal kommen wird, um Thredd zu besuchen.", objectives = "Bringt die versiegelte Beschreibung von Thredds Besucher nach Stormwind zu Baros Alexston.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[393] = { title = "Schatten der Vergangenheit", description = "Ich habe wirklich keine Ahnung, $n. Aber es gibt da jemand anderen, der Euch vielleicht helfen kann, und wie es der Zufall so will, schuldet dieser Jemand mir einen Gefallen, weil... egal, das brauchen wir jetzt nicht zu vertiefen. Ihr könnt Meister Mathias Shaw vom SI:7 in der Kaserne in der Altstadt finden. Shaw hat seine Finger in den meisten zwielichtigen oder heimlichen Geschäften der Stadt.\n\nWenn also jemand etwas weiß, dann er.", objectives = "Bringt die versiegelte Beschreibung von Thredds Besucher nach Stormwind zu Meister Mathias Shaw.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[394] = { title = "Der Kopf des Ganzen", description = "Sucht Shaw in der Altstadt. Teilt ihm mit, dass Ihr Euch um die Bedrohung durch Lescovar gekümmert habt, und berichtet ihm von Eurer Beteiligung an den Plänen des Lords gegen die Stadt. Ich bin sicher, er wird stolz sein, einen weiteren Helden unter den Bürgern Stormwinds zu haben.\n\nEr wird Euch ganz bestimmt zu einem Treffen mit dem Prinzen oder einem anderen Adligen schicken. Lasst Euch das nicht zu Kopfe steigen, $N. Die Adligen können noch so sehr glauben, dass sie die Stadt beherrschen, aber einige Dinge bleiben für die im Dunklen.", objectives = "Sprecht mit Mathias Shaw in Stormwind.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[395] = { title = "Das Ende der Bruderschaft", description = "Ach, das hätte ich fast vergessen. Alexston kam vorbei, als Ihr unterwegs wart, und wünschte mit Euch zu sprechen. Zweifellos möchte er den Adligen über die Ränkespiele der Defiasbruderschaft berichten.\n\nEin kleiner Rat, $n: Sollte Euch jemand fragen, würde ich zwar alle Details offen legen, aber dabei nicht erwähnen, dass es Eure Hand war, die Lescovar erschlug. Vertraut mir. Ich... kenne mich aus... mit solchen Dingen.\n\nUnd was Trias angeht, nun, sprecht mit niemandem über ihn... niemals... wenn Ihr es vermeiden könnt.", objectives = "Sprecht mit Baros Alexston in Stormwind.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[396] = { title = "Eine Audienz beim König", description = "Ich habe einen Bericht an den König vorbereitet. Und Ihr sollt sein Überbringer sein, zusammen mit einer Auflistung Eurer Ergebnisse. Macht Euch keine Sorgen, er wird Euch zweifellos für die Erfüllung Eurer Pflicht gegenüber den Leuten von Stormwind loben.\n\nEure Audienz findet in Kürze statt, also solltet Ihr Euch besser beeilen, denn es ist schon ein Stück Weges bis zur Burg Stormwind.", objectives = "Liefert Baros Alexstons Bericht über die Bruderschaft der Defias bei König Varian Wrynn in der Burg Stormwind ab.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[397] = { title = "Ihr habt uns gut gedient", description = "Wie ich höre, hat Lord Wishock sein Getränk genossen. \n\nIhr habt uns gut gedient, $N. Die Hexenmeister von Stormwind werden nun, dank Euch, ohne Störung ihrem Tagewerk nachgehen können. Ich habe ein besonderes Geschenk vorbereitet, um Euch für Eure Mühen zu entlohnen. Sprecht mit meinem Diener, Zggi, um Eure Belohnung zu erhalten.", objectives = "Sprecht mit Zggi, dem Diener von Zardeth von den Blackclaw, um Eure Belohnung zu erhalten.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[398] = { title = "GESUCHT: Madenauge", description = "Gesucht: Madenauge!\n\nDie selbst für einen Gnoll außerordentlich niederträchtige Kreatur wurde für ihre Verbrechen an den Verlassenen zum Tode verurteilt. Dieser verabscheuungswürdige Verbrecher hat Leichen für die Armee des Lichkönigs gestohlen. Madenauge wurde zuletzt gesehen, als er die Gegend nahe Garrens Schlupfwinkel nördlich von Brill plünderte.\n\nDie Stadt Brill bietet hiermit eine Belohnung für die fähige Seele, die die Exekution durchführt. Zeigt Exekutor Zygand die Tatze des Verbrechers, wenn die Tat getan ist.\n\nGnade ist etwas für die Schwachen.", objectives = "Tötet Madenauge und kehrt dann mit seiner Tatze zu Exekutor Zygand nach Brill zurück, um eine Belohnung zu erhalten.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[399] = { title = "Ein bescheidener Anfang", description = "Es kommt mir so vor, als wäre es ewig her, dass ich als Junge in Westfall auf dem Hof gearbeitet habe. Man sagt ja, man kann niemals in der Zeit zurückgehen, und es stimmt wohl. In meinem Fall trifft das sogar gleich doppelt zu, denn das Heim meiner Familie wurde niedergebrannt und von Dieben besetzt.\n\nIch habe mit meinem Vater über den Verbleib einiger meiner Habseligkeiten gesprochen, darunter mein erster Kompass. Er konnte sie nicht retten. Allerdings meint er auch, dass sie auf dem Hof versteckt sein müssten.\n\nIhr findet den Alexstons Bauernhof westlich der Späherkuppe. Könntet Ihr vielleicht dorthin gehen und mir meinen Kompass wiederbringen?", objectives = "Begebt Euch zu Baros Alexstons Haus in Westfall und sucht nach seinem Kompass. Übergebt ihm diesen dann am Kathedralenplatz von Stormwind.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[400] = { title = "Werkzeuge für Steelgrill", description = "Beldin Steelgrill ist der Besitzer der örtlichen Maschinenschlosserei, und er ist der beste Monteur von Belagerungsmaschinen, den es gibt! Allerdings geht er nicht sehr gnädig mit seinen Werkzeugen um. Ich schwöre Euch, er macht bald mehr Bogenlichtschraubenschlüssel kaputt, als wir ihm liefern können!\n\nWir haben gerade seine letzte Werkzeugbestellung fertig. Wenn Ihr sie ihm anliefert, wird er sich sicherlich erkenntlich zeigen.\n\nSein Geschäft, Steelgrills Depot, liegt etwas nordöstlich von Kharanos. Und nebenbei, es handelt sich dort um einen örtlichen Treffpunkt für die Veteranen unter den Piloten der Belagerungsmaschinen, also hört Euch ruhig ein wenig um, während Ihr dort seid.", objectives = "Liefert Beldin Steelgrill seine Werkzeuge.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[401] = { title = "Wartet, bis Sirra fertig ist", description = "Ich bin fast mit der Übersetzung dieser Notiz fertig. Wenn Ihr in ein paar Minuten wiederkommt, dürfte ich fertig sein.", objectives = "Wartet einen Moment und sprecht dann erneut mit Sirra Von'Indi.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[403] = { title = "Das bewachte Fass mit Donnerbier", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[404] = { title = "Eine eitrige Aufgabe", description = "Teile der Geißel sind nach und nach in Tirisfal eingedrungen und suchen die Gegend westlich von Brill heim, nahe der alten Brücke.\n\nGeht dorthin und schlagt die Faulenden Toten und Verheerten Kadaver zurück, die Ihr dort vorfindet. Zerstreut ihre Knochen und bringt uns ihre eitrigen Klauen, dann werden die Todeswachen Euch entlohnen.", objectives = "Bringt Todeswache Dillinger in Brill 7 eitrige Klauen.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[405] = { title = "Der abtrünnige Lich", description = "Bethor Iceshard, ein hochrangiger und mächtiger Magier aus Undercity im Süden, befiehlt mir, ihm einen Agenten zu schicken, der seinen Wert gegen die Geißel bereits bewiesen hat. Ihr, $N, werdet dieser Agent sein.\n\nZeigt Bethor diese Befehle. Er wird Euch daraufhin über Eure Mission aufklären. Ich kenne keine Details, aber es hat etwas damit zu tun, einen eigenwilligen Lich zu rekrutieren. Und es wird gefährlich sein.\n\nAlso macht Euch bereit, $C. Ihr dürft nicht scheitern.\n\nIhr dürftet Bethor im Magieviertel von Undercity finden.", objectives = "Zeigt Bethor Iceshard in Undercity Sevrens Befehle.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[407] = { title = "Felder des Kummers", description = "Harmlose Kürbisse, oder? Zumindest sehen sie so aus. Wenn wir Arthas' Vormarsch im Norden und die menschliche Plage im Süden stoppen wollen, müssen wir alle Möglichkeiten unseres untoten Daseins nutzen.\n\nMit etwas Einfallsreichtum wird sogar aus einem einfachen Kürbis ein Agent für unsere Dunkle Fürstin. Dieser Kürbis wird sich, wenn nach meiner jüngsten Formel behandelt, als eine besondere Leckerei erweisen.\n\nEs wurde schon wieder ein Scharlachroter Zelot gefangen genommen, der derzeit im Keller der Taverne Zur Galgenschlinge gefangen gehalten wird. Bringt dem Trottel diesen Kürbis.", objectives = "Bringt den getränkten Kürbis zum gefangenen Scharlachroten Zeloten, der im Keller der Taverne Zur Galgenschlinge gefangen gehalten wird.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[408] = { title = "Die Familiengruft", description = "Die Gegend um Agamands Mühlen hat sich zu einem Außenposten der Geißel entwickelt. Am stärksten sind sie in der Gruft der Familie Agamand, wo ihr örtlicher militärischer Anführer, ein Skelett namens Captain Dargol, sein Hauptquartier hat. Er hat die Vorfahren der Agamands durch Nekromantie wiedererweckt und hat vor, sie gegen uns einzusetzen.\n\nDies darf nicht geschehen, und Ihr müsst es verhindern. Reist zur Gruft der Familie Agamand und besiegt die erweckten Vorfahren der Agamands.\n\nUnd bringt mir den Schädel von Captain Dargol.", objectives = "Tötet 8 Klagende Vorfahren und 8 Faulende Vorfahren.\n\nTötet Captain Dargol und bringt seinen Schädel zu Magistrat Sevren nach Brill.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[409] = { title = "Treuebeweis", description = "Ihr behauptet, Ihr wärt nicht dem Willen des Lichkönigs unterworfen, und die Verzauberung, die Bethor auf mein Buch legte, untermauert dies. Aber bevor ich Euch glaube, muss ich den Beweis haben, dass Ihr der Geißel feindlich gegenübersteht.\n\nEs gibt einen alten, blutigen Altar kurz vor der Südküste dieser Insel. Er wird von einer mächtigen Dienerin der Geißel, Lillith Nefara, verwendet.\n\nNehmt eine Kerze des Heranlockens aus dieser Kiste hier. Entzündet sie auf dem Altar, und Lillith wird erwachen. Vernichtet Lillith, und ich werde Euch glauben, dass Ihr ein Gegner des Lichkönigs seid.", objectives = "Beschafft Euch eine Kerze des Heranlockens.\n\nBeschwört Lillith Nefara und tötet sie.\n\nKehrt zu Gunther auf seiner Insel zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[410] = { title = "Der Schlummernde Schatten", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[411] = { title = "Die Rückkehr des abtrünnigen Lichs", description = "Bringt meinem alten Kameraden Bethor diesen Netheredelstein. Er wird uns ermöglichen, miteinander zu kommunizieren... und ich habe ihm eine Menge zu erzählen.", objectives = "Bringt den Netheredelstein zu Bethor Iceshard nach Undercity.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[412] = { title = "Operation Rekombobulationsgerät", description = "Nach genauerer Analyse der Situation in Gnomeregan sieht es so aus, als hätten wir nicht nur dabei versagt, die Troggs auszulöschen, sondern als hätten wir dabei auch noch einen Großteil des Volkes der Gnome in schreckliche, hirnlose, bösartige Lepragnome verwandelt.\n\nOzzie und ich haben vor, den schrecklichen Lepraeffekt mit unserer jüngsten Erfindung wieder rückgängig zu machen: der Rekombobulator. Die Maschine ist beinahe fertig, aber wir brauchen dringend einige Restabilisationszahnräder und gyromechanische Getriebeteile. Besorgt uns ein paar davon bei den Lepragnomen drüben in Gnomeregan.", objectives = "Bringt Razzle Sprysprocket in Kharanos 8 Restabilisationszahnräder und 8 gyromechanische Getriebeteile.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[413] = { title = "Schimmerstarkbier", description = "Ich möchte, dass mein Bruder Wellart mein neues Schimmerstarkbier ausprobiert. Er ist Gebirgsjäger und im südlichen Wachturm stationiert, einem von zwei Türmen an der Grenze zum Loch Modan.\n\nEr mag vielleicht kein Bierbrauer sein wie der Rest von uns Gerstenbräus, aber er trinkt gern mal einen, und ich bin mir sicher, er wird dies hier mögen.\n\nKönnt Ihr ihm dieses Fass Schimmerstarkbier für mich bringen?", objectives = "Bringt das Fass mit Schimmerstarkbier zu Gebirgsjäger Gerstenbräu.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[414] = { title = "Starkbier für Kadrell", description = "Ich habe inzwischen mehr von diesem Schimmerstarkbier getrunken, das mein Bruder gebraut hat - das ist großartiges Zeug! Ein Gebirgsjägerkumpel von mir muss das mal probieren. Er heißt Kadrell und patrouilliert normalerweise entlang der Straße durch Thelsamar beim Loch Modan.\n\nUm nach Thelsamar zu gelangen, müsst Ihr südostwärts durch den Tunnel gehen und dann nach Nordosten abbiegen, wenn der Pfad auf eine Straße trifft. Dieser Straße folgt Ihr direkt bis nach Thelsamar.\n\nGebt Gebirgsjäger Kadrell dieses Fässlein Schimmerstarkbier und schaut mal, was er davon hält!", objectives = "Bringt das Fässlein mit Schimmerstarkbier zu Gebirgsjäger Kadrell.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[415] = { title = "Rejolds neues Gebräu", description = "Rejold Gerstenbräu aus Brewnall hat nach Euch gefragt.\n\nEr möchte mit Euch über ein neues Getränk reden, das er gebraut hat... er sagte etwas davon, dass Ihr ihm vielleicht dabei helfen könntet. Vielleicht wollt Ihr also wieder nach Brewnall zurückkehren, um herauszufinden, worum es geht.\n\nEs könnte etwas Freibier für Euch drin sein...", objectives = "Sprecht mit Rejold Gerstenbräu.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[416] = { title = "Rattenfang", description = "Wir haben im Westen ein Problem mit einer echten Plage. Kobolde der Tunnelratten sind ins Vorgebirge eingedrungen, haben dort ihre Baue eingerichtet und verdrecken unser Land mit ihrem Abfall!\n\nWir wollen, dass sie ausgelöscht werden. Jagt sie, bringt mir ihre Ohren und kassiert das Kopfgeld.\n\nIhr findet die Kobolde der Tunnelratten und ihre Baue westlich von Thelsamar überall über den Berghang verteilt.", objectives = "Bringt Gebirgsjäger Kadrell in Thelsamar 12 Tunnelrattenohren.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[417] = { title = "Pilotenrache", description = "Hildelve schrieb in sein Tagebuch, dass er von Marterklaue, einem \"gewaltigen Eisklauenbären\", angegriffen wurde. Er hat die Bestie verjagt, aber nicht, ohne vorher übel zugerichtet zu werden.\n\nWenn man sich den Zustand von Hildelves Leiche so ansieht, muss Marterklaue später wiedergekommen sein und ihn getötet haben.\n\nJedenfalls schrieb Hildelve in sein Tagebuch einen letzten Wunsch:\n\nRache an Marterklaue.", objectives = "Tötet Marterklaue.\n\nBringt Pilot Hammerfoot die räudige Klaue des Bären und Hildelves Tagebuch.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[418] = { title = "Thelsamar-Blutwurst", description = "Es gibt hier in Thelsamar immer genug Mäuler zu stopfen, mit all den Kindern, die ein und aus gehen, und den Arbeitern von den Ausgrabungsstätten, die nach einem arbeitsreichen Tag hereinkommen. Wir sind berühmt für unsere Blutwurst, Ihr habt sie nicht zufällig schon einmal probiert?\n\nNein? Nun, hierzulande muss man für seine Mahlzeiten arbeiten, und glaubt nur nicht, dass Ihr eine Ausnahme seid, nur weil Ihr ein toller $C seid.\n\nIch brauche Bärenfleisch, Ebergedärme für die Pelle und Spinnensekret als Würzmittel. Bringt mir das alles und überlasst dann Vidra das Kochen!", objectives = "Bringt Vidra Hearthstove in Thelsamar 3 Stück Bärenfleisch, 3 Portionen Ebergedärme und 3 Portionen Spinnensekret.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[419] = { title = "Der vermisste Pilot", description = "Mein Freund Mori Hildelve, ebenfalls ein Pilot der Belagerungsmaschinen, hat sich in den Hügeln verirrt. Wir haben nach einem seltenen Erz gesucht, das man für hochwertiges Sprengpulver benötigt, und während unserer Suche hat er seine Maschine einen steilen Hügel hinaufgefahren und sie dabei kaputt gemacht!\n\nImmer noch überzeugt davon, dass es in diesen Bergen Erz gibt, hat er mich beauftragt, unsere Maschinen zu bewachen, während er zu Fuß weitersuchen wollte.\n\nDas ist jetzt mehrere Tage her, und ich habe in den Hügeln des Nachts das Knurren von Raubtieren gehört. Mori ist ein zäher Bursche, aber ich mache mir Sorgen.\n\nBitte, $N. Sucht ihn.", objectives = "Findet Pilot Hildelve.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[420] = { title = "Senirs Beobachtungen", description = "Die Troggs im Tunnel sind extrem feindselig und scheinen nicht zu zögern, durch den Tunnel reisende Leute anzugreifen. Ihr seid aber offenbar hart genug im Nehmen, also solltet ihr wahrscheinlich sicher sein.\n\nEine Wegbeschreibung? Wenn Ihr mit Senir sprechen wollt, findet Ihr ihn in Kharanos.\n\nArbeitet Euch durch den Tunnel und folgt einfach weiter der Straße, wenn Ihr auf der anderen Seite herauskommt, denn sie führt direkt nach Kharanos.", objectives = "Überbringt Senir Whitebeard in Kharanos Grelins Bericht.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[421] = { title = "Wertbeweis", description = "Lady Sylvanas hat Varimathras damit beauftragt, die Gebiete der Menschen und Zwerge im Süden zu erobern.\n\nAber dieser Idiot Arugal - ein Scharlatan aus Dalaran und heutzutage eine verfluchte Kreatur der Burg Shadowfang - hat auf verantwortungslose Weise mit seiner Magie den strategischen Stützpunkt des Silberwaldes verheert.\n\nIch brauche einen geschickten Kämpfer, der dabei hilft, die Suppe auszulöffeln, die Arugal uns eingebrockt hat. Beweist Euch mir, indem Ihr 5 Moonrage-Weißskalps tötet. Man findet die elenden Bestien oft nur ein kleines Stück abseits der Straße, am Fuße des Hügels dort unten.", objectives = "Dalar Dawnweaver auf dem Grabmal will, dass Ihr 5 Moonrage-Weißskalps tötet.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[422] = { title = "Arugals Torheit", description = "Wie Arugal in die Kirin Tor aufgenommen wurde, ist mir schleierhaft. Seine Zauberkunst schien so billig wie schlecht nachgemachter Schmuck.\n\nAm wichtigsten ist es erst einmal, herauszufinden, welche Art von Magie Arugal genau verwendet hat, damit ich sie gegen ihn verwenden und den Silberwald für die Dunkle Fürstin einnehmen kann.\n\nArugal hielt sich zuerst auf der Weizenfarm etwas nördlich der Brücke auf. Einer der Todespirscher berichtete, dass er einige Zauberbücher gesehen hätte, sie aber nicht beschaffen konnte. Beschafft mir den Zauber namens 'Arznei des Arugal' aus diesen Büchern.", objectives = "Beschafft Dalar Dawnweaver auf dem Grabmal die Arznei des Arugal.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[423] = { title = "Arugals Torheit", description = "Bei der Untersuchung von Arugals Arbeit haben sich meine schlimmsten Befürchtungen bestätigt. Der alte Taugenichts war nicht einmal qualifiziert genug, um die Nachttöpfe in Dalaran zu leeren, davon, die Kirin Tor in ihrer schwersten Stunde zu repräsentieren, ganz zu schweigen. Narren!\n\nArugal benutzte verzauberte Gegenstände, um seine schwache Magie zu verstärken. Ich muss diese Gegenstände selbst untersuchen. Zieht los und erschlagt so lange Moonrage-Nimmersatts und Moonrage-Dunkelseelen, bis Ihr genug ihrer verzauberten Fesseln für meine Nachforschungen gesammelt habt. Man hat diese üblen Kreaturen im Norden und Osten gesehen.", objectives = "Bringt Dalar Dawnweaver am Grabmal 6 Nimmersattfesseln und 3 Dunkelseelenfesseln.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[424] = { title = "Arugals Torheit", description = "Ich werde tatsächlich länger brauchen, als ich gedacht hätte, die dunklen Geheimnisse hinter den Verzauberungen, die Arugal verwendete, zu entdecken.\n\nIn der Zwischenzeit müsst Ihr Euch um ein kleines Problem kümmern, das unsere Dunkelpirscher entdeckt haben. Es sieht so aus, als hätte Arugal seiner Magie erlaubt, sich bis zur Tiefenfelsmine in den Hügeln im Südosten auszubreiten.\n\nDiese Mine wäre eine ziemlich nützliche Ressource für Varimathras' Vormarsch.\n\nIch will, dass Ihr Grimson den Blassen, den besudelten Großknecht der Mine, enthauptet. Mit seinem Tod sollte die Mine uns gehören.", objectives = "Tötet Grimson den Blassen und bringt seinen Kopf zu Dalar Dawnweaver auf das Grabmal.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[425] = { title = "Ivar der Verfaulte", description = "Mein Bruder Quinn und ich wurden beauftragt, den Silberwald auszukundschaften und Hochexekutor Hadrec Bericht zu erstatten. Aber wir kamen nicht weit - als wir über diese Farm gingen, wurden wir von einem Ghul namens Ivar der Verfaulte angegriffen.\n\nWir entkamen Ivar, aber er verletzte Quinn schwer. Dank des Trankes, den Ihr ihm gegeben habt, heilt er, aber Ivar könnte wiederkommen, bevor Quinn sich erholt hat.\n\nTötet Ivar, damit Quinn genug Zeit hat, sich zu regenerieren. Ivar hält sich üblicherweise in dem Schuppen da drüben auf und wartet darauf, dass meine Wachsamkeit nachlässt.", objectives = "Tötet Ivar den Verfaulten und bringt Ivars Kopf zu Rane Yorick auf dem Ivar-Feld.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[426] = { title = "Die überrannte Mühle", description = "Die Geißel versucht, bei Agamands Mühlen einen Stützpunkt zu errichten. Wenn ihnen das gelingt, können sie weitere Angriffe innerhalb von Tirisfal unternehmen.\n\nEs wurden klare Befehle erteilt. Die Diener der Geißel in den Mühlen müssen vernichtet werden.\n\nGeht zu den Mühlen. Sammelt schartige Rippen von klappernden Skelettsoldaten und Trümmerschädelsoldaten sowie geschwärzte Schädel von dunklen Skelettmagiern.\n\nUm zu den Mühlen zu gelangen, folgt der Straße westwärts. Nachdem Ihr die Brücke überquert habt, nehmt die erste Abzweigung nach Norden und folgt diesem Weg. Wenn Ihr die Windmühlen seht, beginnt die Schlacht.", objectives = "Sammelt 5 schartige Rippen sowie 3 geschwärzte Schädel und kehrt dann zu Todeswache Dillinger nach Brill zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[427] = { title = "Im Krieg mit dem Scharlachroten Kreuzzug", description = "Die Dokumente, die Exekutor Arren uns zur Verfügung stellte, verschaffen uns genau die Atempause, die wir in unserem Kampf gegen den Scharlachroten Kreuzzug benötigen. Wir kennen jetzt dessen genaue Aufenthaltsorte überall in Tirisfal.\n\nAber leider haben die Todeswachen noch ganz andere Sorgen. Die Armee des Lichkönigs wächst jede Nacht an. Wir benötigen jemanden, der wie Ihr gern \"Initiative\" zeigt, um den Scharlachroten Kreuzzug ins Grab zu bringen.\n\nBeweist mir, dass Ihr der Dunklen Fürstin dienen könnt, indem Ihr nach Westen zum Turm hinter Sollidens Bauernhof reist und dort 10 Scharlachrote Krieger erschlagt.", objectives = "Exekutor Zygand von Brill verlangt, dass Ihr 10 Scharlachrote Krieger tötet.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[428] = { title = "Die verlorenen Todespirscher", description = "Vor einigen Wochen wurden zwei unserer Todespirscher, Rane und Quinn Yorick, auf eine Aufklärungsmission durch den nördlichen Silberwald geschickt. Wir haben nichts mehr von ihnen gehört.\n\nSie könnten der Geißel zum Opfer gefallen sein, doch wenn dem so ist, will ich es bestätigt wissen. Findet diese Todespirscher.\n\nIhre erste Aufgabe war es, die Bauernhöfe im nördlichen Silberwald auszukundschaften. Ihr solltet dort mit Eurer Suche beginnen.", objectives = "Findet die Todespirscher Quinn und Rane Yorick.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[429] = { title = "Wilde Herzen", description = "Mein Bruder Quinn wurde von dem Ghul Ivar dem Verfaulten schwer verletzt, und ich glaube nicht, dass er ohne magische Hilfe wieder vollständig genesen wird. Auch wenn ich kein Apotheker bin, so weiß ich doch, dass unsere Apotheker Heiltränke aus verfärbten Worgherzen herstellen können.\n\nSammelt einige solcher Herzen und bringt sie zu Apotheker Renferrel am Grabmal im Süden. Kommt dann mit dem Trank hierher zurück.\n\nZwischen hier und Maldens Obsthain im Osten werdet Ihr jede Menge Worgs vorfinden.", objectives = "Sammelt 6 verfärbte Worgherzen und bringt sie zu Apotheker Renferrel auf dem Grabmal.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[430] = { title = "Rückkehr zu Quinn", description = "Hier habt Ihr den Trank, mit dem Ihr Quinn Yoricks Erholung beschleunigen könnt.\n\nWenn Ihr mich jetzt entschuldigen mögt, ich habe wirklich wichtige Dinge zu erledigen...", objectives = "Bringt Quinn Yorick auf dem Ivar-Feld, nördlich des Grabmals, Quinns Trank.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[431] = { title = "Kerze des Heranlockens", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[432] = { title = "Diese verfluchten Troggs!", description = "Diese vom Licht verfluchten Troggs verwandeln meinen Arbeitsplatz in eine Ruine. Schaut Euch das an, da geht schon wieder ein Pulverfass hoch.\n\nOh, ich wünschte ich könnte da runtergehen und allen einzeln ihre dürren Hälse umdrehen! Ich will sie alle töten!\n\nDas kann nicht gut für meine Gesundheit sein, all dieser Stress und diese Wut... Was haben sie mir gelassen? Nichts!\n\nIch würde sie persönlich umbringen, aber ich ziele nicht mehr so gut wie früher. Geht in den Steinbruch und tötet einige dieser dreckigen Mistviecher! Ich werde Euch bezahlen! Hauptsache, Ihr verletzt sie, tötet sie!", objectives = "Tötet für Großknecht Stonebrow im Gol'Bolar Steinbruch 6 Schädelhauer der Felsenkiefer.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[433] = { title = "Im Dienste des Volkes", description = "Als Mitglied des Senats und der Forscherliga habe ich mir vorgenommen, mich um den Teil der Trogg-Plage zu kümmern, die unser Land heimsucht.\n\nSie haben den Gol'Bolar Steinbruch wirklich ziemlich verwüstet, und das ohne erkennbaren Grund. Als wir tiefer in die Erde hineingruben, strömten sie heraus, zerstörten unsere Ausrüstung und verjagten die Minenarbeiter. Wir können nicht viel mehr tun, als das ganze Pack auszulöschen, alles wieder aufzubauen und dann wieder an die Arbeit zu gehen.\n\nWenn Ihr mir mit den Troggs helft, werde ich Euch gern für Eure Zeit, die Ihr dafür opfert, entschädigen.", objectives = "Tötet für Senator Mehr Stonehallow im Gol'Bolar Steinbruch 10 Knochenknacker der Felsenkiefer.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[434] = { title = "Der Angriff!", description = "Nachdem ich dem Spionagebot die Verkleidung angelegt habe, begibt er sich hinein, um mit Lescovar zu sprechen. Die Wachen sollten ihn ohne Probleme durchlassen.\n\nWährend Ihr Material für mich gesammelt habt, habe ich Marzon darüber informiert, dass es für ihn und Lescovar an der Zeit sei, sich wieder zu treffen. Ich habe sogar einige falsche Informationen verlautbaren lassen.\n\nLescovar wird seine Wachen wegschicken und hier draußen im Garten auf Marzon warten. Tretet in Aktion, wenn Ihr etwas über die Defias hört. Ihr müsst sie beide eliminieren. Kapiert?\n\nWenn Ihr das erledigt habt, sprecht Ihr mit Trias.", objectives = "Bleibt im Garten, bis Lord Gregor Lescovar und Marzon die Stille Klinge ihr Gespräch beendet haben. Schaltet sie danach beide aus, bevor Ihr nach Stormwind zu Elling Trias zurückkehrt.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[435] = { title = "Eskorte für Erland", description = "Die Wölfe da draußen wollen nicht abhauen, und jedesmal, wenn ich einen Schritt aus der Tür mache, schauen sie mich böse an. Sie müssen unglaublich hungrig sein, wenn sie mich für essenswert halten.\n\nIch muss mich bei meiner Kampfgefährtin, Todespirscherin Rane Yorick, melden. Und um zu Rane zu kommen, brauche ich Hilfe gegen diese Wölfe.\n\nBitte begleitet mich! Ach ja, da draußen sind eine Menge Wölfe, wir hätten also eine bessere Chance, wenn Ihr Freunde dabei hättet, die ebenfalls helfen können...", objectives = "Begleitet Erland durch die Wölfe hindurch zu Rane Yorick.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[436] = { title = "Ironbands Ausgrabungsstätte", description = "Ausgrabungsleiter Ironband leitet die Ausgrabung einiger alter Ruinen östlich des Sees. Er hat zuletzt wenig Fortschritte gemacht, besonders, wenn man all den Nachschub bedenkt, den wir ihm geschickt haben.\n\nIronband ist ein bodenständiger, ehrlicher Zwerg, der gern Resultate sieht, und daher mache ich mir Sorgen, dass da irgendwelche Kräfte gegen ihn arbeiten.\n\nGeht zu Ironbands Ausgrabungsstätte und sprecht mit Magmar Fellhew. Er kümmert sich um die Einzelheiten an der Stätte und wird wissen, warum es so langsam voran geht.\n\nUm zur Ausgrabungsstätte zu gelangen, müsst Ihr um die Südspitze des Sees herum und dann nach Osten gehen.", objectives = "Sprecht mit Forscher Fellhew.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[437] = { title = "Das Todesfeld", description = "Unsere ursprünglichen Spähberichte über den Silberwald zeigen, dass die Moderfelle auf einer alten Farm im Norden, nahe dem Todesfeld, einen Stützpunkt haben. Wir haben kleine Angriffe auf sie gestartet, aber jedesmal werden sie von der Banshee Nachtseele unterstützt, die ihre Magie einsetzt, um unsere Truppen in die Flucht zu schlagen.\n\nWir wollen Nachtseele vernichtet sehen.\n\nGeht ins Todesfeld und greift die Moderfelle an. Falls Ihr Nachtseele nicht seht, tötet so lange Moderfellgnolle, bis sie auftaucht, und besiegt sie dann.\n\nIhre Essenz wird zu Staub zerfallen. Bringt mir diesen Staub als Beweis.", objectives = "Tötet Gnolle der Moderfelle auf dem Todesfeld.\n\nSobald Nachtseele auftaucht, tötet sie ebenfalls.\n\nBringt Nachtseeles Essenz zu Hochexekutor Hadrec auf das Grabmal.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[438] = { title = "Die verfallene Fähre", description = "$n, wir haben ein neues Nest der Geißel entdeckt: Die verfallene Fähre. Die Fähre liegt östlich des Grabmals und wird von Moderfellgnollen und anderen Untoten schwer bewacht.\n\nEs muss einen Grund dafür geben, warum die Geißel dieses Gebiet besetzt hat. Geht zur verfallenen Fähre und findet heraus, warum die Geißel sich dort aufhält.", objectives = "Geht zur verfallenen Fähre.\n\nSucht nach dem Grund, warum die Geißel dort ist.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[439] = { title = "Auf den Spuren der Moderfelle", description = "Aus den Leichen ragt eine nicht eingewickelte Hand heraus. Es handelt sich um die Hand einer Frau, von der Seuche pockennarbig, aber relativ frisch. \n\nAn der Hand befindet sich ein Ring. Als Ihr den Ring entfernt und untersucht, entdeckt Ihr eine Gravur:\n\n\"Für Deliah\".", objectives = "Bringt Deliahs Ring zu Hochexekutor Hadrec auf das Grabmal.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[440] = { title = "Der gravierte Ring", description = "Wenn Ihr den Ehemann oder Geliebten finden wollt, der Deliah ihren Ring gab... dann sprecht mit Magistrat Sevren in Brill. Er sollte alle Dokumente über die jüngsten Todesfälle haben und wird mit etwas Glück herausfinden können, wer Deliah ist.\n\nAber ich würde meine Hoffnungen nicht zu hoch stecken. Wer auch immer ihr den Ring gab, ist wahrscheinlich tot. Oder, wenn er untot ist, kümmert Deliah ihn wahrscheinlich nicht mehr.", objectives = "Bringt Deliahs Ring zu Magistrat Sevren nach Brill.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[441] = { title = "Raleigh und Undercity", description = "Deliah hatte einen Ehemann, Raleigh, der nun in Undercity sein Zuhause hat. Wenn die Deliah, die in Brill wohnte, die ist, der dieser Ring gehörte, dann wird es Raleigh wissen.\n\nRaleigh ist im Handwerksviertel von Undercity.", objectives = "Bringt Deliahs Ring zu Raleigh.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[442] = { title = "Sturm auf die Insel Fenris", description = "Es ist an der Zeit, den Standort der Geißel im Silberwald zu stürmen: die Insel Fenris.\n\nIhr müsst Euch noch einmal auf diese Insel begeben und Thule Rabenklaue vernichten. Ich will seinen Kopf!\n\nDiese Mission ist so gefahrvoll, wie sie entscheidend ist, $n. Ihr dürft nicht scheitern.", objectives = "Bringt Hochexekutor Hadrec auf dem Grabmal Thules Kopf.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[443] = { title = "Moderfellsekret", description = "Bevor wir einen Angriff auf die Insel Fenris starten können, müssen wir erst herausfinden, wer hinter den Moderfellgnollen steht. Unsere Apotheker glauben, ihr Ursprung liegt in der seltsamen Flüssigkeit, die durch ihre Körper fließt.\n\nGeht zur Insel Fenris, östlich der verfallenen Fähre, und sammelt Moderfellsekret von den Gnollen dort. Bringt es zu Apotheker Renferrel, draußen vor dem Grabmal.", objectives = "Bringt 8 Flaschen Moderfellsekret zu Apotheker Renferrel auf das Grabmal.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[444] = { title = "Die Ursprünge der Moderfelle", description = "Ich habe das Sekret, das Ihr mir gebracht habt, in seine Grundbestandteile aufgelöst. Meine Ergebnisse sind nicht sehr aufschlussreich, aber ich konnte ermitteln, dass Hexenmeister- und Totenbeschwörermagie zur Herstellung des Sekrets verwendet wurden.\n\nWährend ich weiter das Sekret untersuche, möchte ich, dass Ihr eine Probe davon zu Bethor Iceshard nach Undercity bringt. Bethor ist kein Apotheker, aber sein Wissen von der Magie könnte uns helfen, das Geheimnis um die Moderfelle zu lüften.\n\nGeht. Ihr dürftet Bethor im Magieviertel von Undercity finden.", objectives = "Bringt die Sekretprobe zu Bethor Iceshard nach Undercity.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[445] = { title = "Lieferung in den Silberwald", description = "Zeit ist ein Luxus, den sich diejenigen, die für Lady Sylvanas arbeiten, nicht leisten können. Aber das wisst Ihr inzwischen sicher selbst.\n\nAls Mitglied der königlichen Apothekervereinigung ist es meine Pflicht, mein Wissen mit meinen Kollegen zu teilen, auf dass unsere gemeinsamen Bemühungen der dunklen Fürstin eines Tages die neue Seuche bescheren werden, die sie so ersehnt.\n\nBringt diese Erkenntnisse zu Apotheker Renferrel, der beim Grabmal im Silberwald stationiert ist. Folgt der Straße von Brill aus nach Süden. Geht dann nach Undercity südwestwärts.", objectives = "Bringt Apotheker Johaans Erkenntnisse zu Apotheker Renferrel im Silberwald.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[446] = { title = "Thule Rabenklaue", description = "Dieses Sekret wurde von einem alten Kollegen von mir hergestellt: Thule Rabenklaue. Vor dem großen Krieg war er ein junger, aufstrebender Magier, aber als der Lichkönig immer mächtiger wurde, verriet er seine Brüder und verbündete sich mit der Geißel.\n\nIch hätte nicht gedacht, dass er noch lebt, geschweige denn, dass er die Moderfelle bei ihren Vorstößen gegen uns anführt.\n\nIch kenne viele seiner Zauber und kann dabei helfen, einen Trank zu brauen, der ihnen entgegenwirkt. Nehmt diese Spruchrolle mit zurück zu Apotheker Renferrel. Auf ihr stehen die Beschwörungsformeln, die man für den Trank braucht.", objectives = "Bringt Bethors Spruchrolle zu Apotheker Renferrel auf das Silberwald-Grabmal.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[447] = { title = "Rezept für den Tod", description = "Arthas hat Truppen von schier endloser Zahl. Doch mit einer neuen Seuche könnten wir sowohl die Armee der Geißel als auch das menschliche Ungeziefer ein für alle Mal auslöschen.\n\nMeine Studien haben bewiesen, dass Spinnenblut, vermischt mit einem aus dem Herzen eines ergrauten Bären gewonnenen Toxin, zu einem tödlichen Elixier wird. Sammelt Proben von den Spinnen im Huschdunkel im Nordwesten und von den Bären, die im Silberwald umherstreifen. Bringt diese Reagenzien zu Meisterapotheker Faranell von der königlichen Apothekervereinigung in Undercity.", objectives = "Sammelt 6 Herzen von ergrauten Bären und 6 Proben Huschendes Blut und bringt diese zu Meisterapotheker Faranell nach Undercity.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[448] = { title = "Meldung bei Hadrec", description = "Bevor Ihr einen Angriff auf die Insel Fenris unternehmt, meldet Euch bei Hochexekutor Hadrec. Er könnte zusätzliche Informationen oder Ausrüstung haben, die Ihr brauchen werdet.", objectives = "Meldet Euch bei Hochexekutor Hadrec auf dem Grabmal.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[449] = { title = "Der Bericht der Todespirscher", description = "Auch wenn Quinns Wunden heilen, möchte ich doch unseren Bericht so schnell wie möglich zu Hochexekutor Hadrec bringen. Er enthält Informationen, die für die Besetzung des Silberwaldes durch die Verlassenen von höchster Wichtigkeit sind.", objectives = "Bringt den Todespirscherbericht zu Hochexekutor Hadrec auf das Grabmal.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[450] = { title = "Rezept für den Tod", description = "Ihr könnt der königlichen Apothekervereinigung noch weiter zu Diensten sein, $N.\n\nAls Arugal seine elenden Zauber über den Wald gelegt hat, verfluchte er eines unserer viel versprechendsten Mitglieder, Apotheker Berard. Als hirnloser Diener von Arugal ist Berard jetzt für uns nutzlos. Aber seine Erkenntnisse könnten sich als wertvoll erweisen. Er untersuchte eine längst vergessene Seuche, die vor Ewigkeiten einmal alles Leben im Lordameresee getötet hat.\n\nBergt Berards Tagebuch aus seinem Studierzimmer im Gasthaus von Pyrewood und bringt es zu Apotheker Renferrel.", objectives = "Bergt Apotheker Berards Tagebuch aus Pyrewood und bringt es zu Apotheker Renferrel auf das Grabmal.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[451] = { title = "Rezept für den Tod", description = "Laut Berards Tagebuch könnte sich das Moos von Seeschleichern und Seekrabblern bei unserer Suche nach einer neuen Seuche als nützlich erweisen. Diese Bestien leben auf den Inseln im Lordameresee im Osten.\n\nEr erwähnt außerdem einen sehr seltenen verhärteten Tumor, den er bei einem Finsterflossenmurloc entdeckte. Anscheinend war der Tumor so selten, dass Berard nur einen einzigen auftreiben konnte.\n\nSammelt Proben von diesem Moos sowie von dem seltenen verhärteten Tumor und bringt beides zu Meisterapotheker Faranell nach Undercity.", objectives = "Bringt 6 Proben Seeschleicher-Moos, 6 Proben Seekrabbler-Moos und einen verhärteten Tumor zu Meisterapotheker Faranell nach Undercity.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[452] = { title = "Der Pyrewood-Überfall", description = "Ihr kommt gerade rechtzeitig, $N!\n\nDer Rat von Pyrewood wird jeden Moment zurückkehren. Arugal muss sich in der Burg um andere Dinge kümmern. Er benutzt den Rat als reine Schachfiguren, um die hirnlosen Diener von Pyrewood unter seiner Kontrolle zu halten. Aber ich glaube, dass die Söhne von Arugal sich ohne die Führung durch den Rat von Pyrewood gegen ihren Meister stellen werden.\n\nIch werde nicht allein mit ihnen allen fertig. Ihr müsst mir helfen. Gemeinsam können wir den Rat für Lady Sylvanas zerschlagen.", objectives = "Helft Todespirscher Faerleia, den Rat von Pyrewood zu töten.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[453] = { title = "Auf der Suche nach der Schattengestalt", description = "Viel Glück, $n. Ich hoffe, Ihr könnt den Kerl finden, und dass er dann noch am Leben ist.\n\nWenn er die Sicherheit von Dunkelhain hinter sich gelassen hat, könnte er leicht Wildtieren zum Opfer gefallen sein.", objectives = "Findet die Schattengestalt. Eure Hinweise:\n\nEr stammt nicht aus Dunkelhain.\n\nEr ist eine nervöse, hektische Person.\n\nEr verließ Dunkelhain und ging nach Westen.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[454] = { title = "Nach dem Hinterhalt", description = "Wir hatten vor dieser... Geschichte die Pulverfässer in mehreren Fuhren transportiert. Jetzt müssen wir die Arbeit aufteilen. Miran nimmt die Fässer, und ich passe auf die anderen auf.\n\nIch fühle mich nicht wohl dabei, Miran den Rest der Fracht ganz allein transportieren zu lassen. Vielleicht könntet Ihr ihn auf seiner nächsten Tour begleiten, wenn er fertig zur Abreise ist?", objectives = "Sprecht mit Miran.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[455] = { title = "Der Algaz-Spießrutenlauf", description = "Orcs vom Dragonmawklan haben im Sumpfland eine Zufluchtstätte. Und jetzt haben sie sich nach Dun Algaz ausgebreitet. Wir können nicht zulassen, dass sie ihren Einfluss auf dieses Gebiet behalten, sonst wird der Loch Modan vom Hafen von Menethil, unserer Hafenfestung im Sumpfland, abgeschnitten.\n\nBrecht durch Dun Algaz in das dahinterliegende Sumpfland durch und tötet dabei ein paar Orcs. Meldet Euch bei Valstag Ironjaw im Hafen von Menethil.\n\nNach Menethil kommt Ihr, indem Ihr Dun Algaz durchquert, anschließend nordwärts der Straße folgt und Euch dann an der Biegung westwärts haltet.\n\nWir verlassen uns auf Euch, $N. Ihr dürft nicht scheitern.", objectives = "Durchquert Dun Algaz.\n\nTötet 8 Späher der Dragonmaw und 6 Grunzer der Dragonmaw.\n\nMeldet Euch bei Valstag Ironjaw im Hafen von Menethil.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[456] = { title = "Das Gleichgewicht der Natur", description = "Seid gegrüßt, $N. Ich bin Konservator Ilthalaine. Meine Aufgabe in Shadowglen ist es, für den Erhalt des Gleichgewichts der Natur zu sorgen.\n\nDie Frühjahrsniederschläge waren dieses Jahr besonders heftig, was dafür sorgte, dass einige Tiere des Waldes gediehen, während andere darunter litten.\n\nUnglücklicherweise sind die Bestände an Nachtsäblern und Distelebern zu stark angewachsen. Shadowglen kann nur eine gewisse Menge Futter für diese Tiere erzeugen. Zieht los, $C, und dünnt die Eber- und die Säblerpopulation etwas aus, auf dass die Harmonie der Natur erhalten bleibt.", objectives = "Tötet 7 junge Nachtsäbler sowie 4 junge Disteleber und kehrt dann zu Konservator Ilthalaine zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[457] = { title = "Das Gleichgewicht der Natur", description = "Die Jungbestände einiger Kreaturen hier im Shadowglen auszudünnen, war ein guter Anfang, $N, aber es gibt immer noch etwas zu tun.\n\nDie Ressourcen des Waldes werden sich zu schnell erschöpfen, wenn sich niemand um das Problem kümmert. Mutter Naturs Wildtiere zu töten, ist ein notwendiges Übel zum Besten von allen, die sich das Land teilen. Begebt Euch in den Wald und erschlagt im Namen des Gleichgewichts räudige Nachtsäbler und Disteleber.", objectives = "Konservator Ilthalaine verlangt von Euch, 7 räudige Nachtsäbler und 7 Disteleber zu töten.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[458] = { title = "Die Beschützerin des Waldlandes", description = "Was ein Glück, dass Ihr hier seid, $C. Vom Wispern der Waldgeister wurden mir seltsame Neuigkeiten zugetragen.\n\nDie geheimnisvolle Beschützerin des Waldlandes, Tarindrella, ist nach Shadowglen zurückgekehrt. Jahrelang war die Gegenwart der Dryade in den Wäldern Kalimdors nicht zu spüren. Sicherlich stimmt irgendetwas nicht, wenn sie jetzt wieder in diese Gegend zurückgekommen ist.\n\nSucht Tarindrella und findet heraus, was sie in unseren Hain führt. Eine der Schildwachen berichtete, sie südwestlich von Aldrassil gesehen zu haben.", objectives = "Sucht die Dryade, die als Tarindrella bekannt ist.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[459] = { title = "Die Beschützerin des Waldlandes", description = "Etwas Böses braut sich im Wald von Teldrassil zusammen. Schaut Euch die Hügel an, in denen die friedlichen Furbolgs früher hausten. Sie haben ihre Heime verlassen und sammeln sich unter dem Banner des Knarzklauenstamms.\n\nNur die Verderbtheit des bösartigen Teufelsmooses könnte eine solche Wandlung geschehen lassen. Die Grells und Grellkin suchen die Gegend heim und bedrohen die Einwohner von Shadowglen. \n\nSpürt diese Grells und Grellkins auf, $N, und überzeugt Euch, ob sie wirklich unter dem Einfluss des bösartigen Teufelsmooses stehen.", objectives = "Sammelt 8 Stücke Teufelsmoos und bringt sie zu Tarindrella.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[460] = { title = "In Stücken begraben", description = "Ihr seht nicht aus wie ein Moderfell. Gut. Ich hatte die Hoffnung schon aufgegeben...\n\nMein Name ist Alaric und ich war einst Thules oberster Diener und Leibwächter. Er nutzte seine Magie, um mich vor der Pest des Untodes zu \"schützen\", ein schöner Schutz... denn sein Zauber bürdete mir ein Unleben auf, dem ich nicht entrinnen kann. Und nachdem er diese verfluchten  der Moderfellgnolle erschaffen hatte, hat Thule mich geköpft... und meinen Kopf den Gnollen zum Spielen gegeben!\n\nBitte, bringt mich zu meinem Körper. Ich glaube, die Gnolle haben ihn hier in der Burg Fenris, nahe den Stallungen, in einem namenlosen Grab verscharrt.", objectives = "Bringt Alarics Kopf zu seinem Grab.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[461] = { title = "Die versteckte Nische", description = "Ich kenne eine versteckte Nische in der Burg, die einen Gegenstand enthält, der für Thule und seine alten Kollegen sehr wichtig ist. Außerdem enthält sie noch etwas, das Ihr nützlich finden könntet. Bringt mich dorthin!\n\nDie Nische ist im Südwestturm der Burg, hinter einem staubigen Regal.\n\nNehmt meinen Körper mit, aber lasst die Stiefel hier. Die haben mir sowieso nie richtig gepasst.", objectives = "Bringt Alaric zur versteckten Nische.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[463] = { title = "Der Sumpfhüter", description = "Ihr habt vom Sumpfhüter gehört? Ihr sucht doch nicht etwa nach ihm, oder? Nun, ich behaupte ja, Ihr seid verrückt, wenn dem so ist, aber wer bin ich, dass ich $geinen Narren:eine Närrin; davon abhalte, in den Tod zu gehen?\n\nFalls Ihr ihn sucht - hmmm, ich habe gehört, er sei in den Marschen, ostwärts von dort, wo die Straße nach Dun Modr abzweigt. Er lungert dort bei den Kroks und Schlimmerem herum!\n\nAch, und lasst Euer Geld besser hier. Ihr werdet es dort, wo Ihr hingeht, nicht brauchen... und Ihr wollt doch sicher nicht, dass der alte Grünling sich an Eurem Gold einen Zahn ausbricht, wenn er Euch mittendurch beißt.", objectives = "Findet den Sumpfhüter.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[464] = { title = "Kriegsflaggen", description = "Der orcische Dragonmawklan war am Ende des zweiten Krieges so gut wie vernichtet, nachdem sie die Kontrolle über ihre Schoßtierchen, die roten Drachen, verloren hatten. Die Drachen waren nicht sehr freundlich zu ihren früheren Herren und machten gnadenlos Jagd auf die Dragonmaw. Die wenigen, die überlebten, flohen aus Grim Batol in die Berge östlich von Whelgars Ausgrabungsstätte.\n\nJetzt haben sie an Stärke gewonnen und besitzen ein Lager nordöstlich von Menethil.\n\nWir wollen, dass Ihr dieses Lager angreift. Sammelt und bringt mir ihre Kriegsflaggen als Beweis.", objectives = "Bringt Captain Stoutfist 8 Kriegsflaggen der Dragonmaw.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[465] = { title = "Nek'roshs Schachzug", description = "Während Ihr die Dragonmaw bekämpft habt, haben wir mehr über deren Pläne herausgefunden.\n\nNek'rosh hat Katapulte gebaut und beabsichtigt, Menethil zu belagern! Und dank der Kämpfe in Dun Algaz sind wir effektiv von Verstärkungen abgeschnitten!\n\nIhr müsst diese Katapulte zerstören. Sie befinden sich im Lager der Dragonmaw.\n\nHier, nehmt diesen Zunder. Kämpft Euch zu den Katapulten durch und lasst sie mit dem Zunder in Flammen aufgehen.\n\nUnd nachdem Ihr das getan habt, findet und tötet Nek'rosh. Wir müssen dieser Dragonmawbestie den Kopf abschlagen.", objectives = "Zerstört die Katapulte der Dragonmaw.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[466] = { title = "Auf der Suche nach Pyrophor", description = "Ich habe gehört, im Sumpfland wurde in einer Höhle nordwestlich vom Algaz-Tor ein seltenes Erz namens Pyrophor gefunden. Pyrophor ist instabil und schwer anzuwenden, ohne sich dabei selbst in die Luft zu sprengen, aber ich bin mir sicher, wenn man es auf die richtige Art und Weise verhüttet, könnte man daraus Kanonenkugeln mit einer ziemlichen Durchschlagskraft herstellen.\n\nBesorgt mir Pyrophorerz und ich finde jemanden, der mutig genug ist, damit zu experimentieren.\n\nOh, und um dieses Erz aus einer Ader zu schürfen, müsst Ihr Euch mit Bergbau auskennen. Wenn dem nicht so ist, dann... nehmt einen Freund mit in diese Höhle, der es tut!", objectives = "Bringt 6 Ladungen Pyrophorerz zu Pilot Stonegear nach Dun Morogh.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[467] = { title = "Stonegears Suche", description = "Pilot Stonegear liebt seine Belagerungsmaschine, wie jeder Pilot es auch sollte! Und er ist immer begierig, neue Wege zu finden, die Feuerkraft seines Panzers zu vergrößern!\n\nEr hat Gerüchte über ein seltenes Erz gehört und sucht jetzt nach jemandem, der es für ihn auftreibt. Wenn es Euch also in den Fingern juckt, dann sucht Stonegear in Steelgrills Depot in Dun Morogh auf und schaut mal, was er will.", objectives = "Sprecht mit Pilot Stonegear.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[468] = { title = "Meldung bei Gebirgsjäger Rockgar", description = "Gebirgsjäger Rockgar sucht nach Freiwilligen für eine Mission durch Dun Algaz und in das Sumpfland hinein. \n\nWenn Ihr also Lust habt, Euch Eure Stiefel in dieser sumpfigen Gegend im Norden schmutzig zu machen, dann sprecht mit Rockgar in Dun Algaz. Dun Algaz liegt weiter die Straße entlang im Norden, hinter dem Wachturm.", objectives = "Sprecht mit Gebirgsjäger Rockgar.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[469] = { title = "Tägliche Lieferung", description = "Seid gegrüßt!\n\nIhr seid nicht zufällig in Richtung Menethil unterwegs? Falls nicht, würde ich Euch empfehlen, dort Halt zu machen, denn es ist ein guter Ort, um Waren zu kaufen oder etwas trinken zu gehen und sich auszuruhen.\n\nTja, wenn Ihr also zufälligerweise in diese Richtung unterwegs seid, dann habt Ihr doch sicher nichts dagegen, dieses Bündel Krokiliskenhäute zu James Halloran, dem Gerber, zu bringen?\n\nIch würde es ja selbst tun, aber meine Frau ist in letzter Zeit ziemlich launisch, und ich würde es gern so lange wie möglich aufschieben, ihr zu begegnen.", objectives = "Liefert das Bündel Krokiliskenhäute bei dem Gerber James Halloran im Hafen von Menethil ab.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[470] = { title = "Stochern im Brühschlamm", description = "Bei meinem wöchentlichen Besuch an Ironbeards Grabmal wurde ich von grässlichen, triefenden Brühschlammern angegriffen! Natürlich geriet ich in Panik.\n\nIch habe meine Tasche nach einem geworfen, aber das zeigte keinerlei Wirkung! Der Brühschlammer saugte sie einfach auf... Glücklicherweise gab mir das genug Zeit wegzulaufen.\n\nDie schlechte Nachricht ist, dass ich dringend den Inhalt meiner Tasche benötige!\n\nIch weiß nicht, nach welchem Brühschlammer ich meine Tasche geworfen habe; sie sehen alle gleich aus! Ironbeards Grabmal liegt nordöstlich von hier, in der Nähe von Dun Modr. Ich danke Euch wirklich sehr!", objectives = "Einer der Brühschlammer bei Ironbeards Grabmal hat Sidas Tasche. Bergt sie und bringt sie ihr zurück in den Hafen von Menethil.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[471] = { title = "Lehrlingspflichten", description = "Ich habe meinen Lehrling in die Marschen geschickt, um einige unserer berühmten riesigen Sumpflandkrokilisken zu häuten. Als er nicht zurückkam, bin ich losgezogen, um ihn zu suchen... Sagen wir einfach, es war kein schöner Anblick.\n\nDie Schwester sagt, er könnte durchkommen, aber derweil brauche ich immer noch meine Häute!\n\nUnd wenn Ihr noch ein paar von den Monstern töten wollt, hätte ich nichts dagegen, nach allem, was sie getan haben. Ihr findet die Kroks, wenn Ihr die Küste entlang nach Norden geht, hinter den Hütten der Murlocs.", objectives = "Sammelt 6 riesige Krokiliskenhäute und bringt sie zu James Halloran in den Hafen von Menethil.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[472] = { title = "Der Fall von Dun Modr", description = "Dun Modr ist an die Dunkeleisenzwerge gefallen!\n\nMeine Wunden sind schwer, $C. Ein Großteil meines Regiments wurde getötet! Diese Rohlinge der Dunkeleisenzwerge haben uns angegriffen, bevor wir uns nach dem Überfall auf den Thandol-Übergang wieder sammeln konnten.\n\nUnser Anführer, Longbraid, blies zum Rückzug. Als wir die Stadt verließen, wurde ich von einer verirrten Axt in den Rücken getroffen und alles wurde schwarz um mich.\n\nIch wachte hier in Menethil auf, aber ich fürchte um meine Kameraden. Ich hege allerdings noch Hoffnung. Vielleicht ist Longbraid noch am Leben! Seht nach, ob Ihr ihn in der Nähe von Dun Modr finden könnt, $R!", objectives = "Sucht nahe der Stadt von Dun Modr nach Longbraid.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[473] = { title = "Meldung bei Captain Stoutfist", description = "$N. Der Dragonmawklan der Orcs zeigt nicht nur in Algaz Stärke. Captain Stoutfist wünscht mit denen zu sprechen, die Hilfe gegen diese Orcs anbieten wollen. Er ist in der Burg, im Kriegsraum.", objectives = "Sprecht mit Captain Stoutfist.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[474] = { title = "Sieg über Nek'rosh", description = "Jetzt, nachdem die Katapulte abgebrannt wurden, sucht und tötet Häuptling Nek'rosh.", objectives = "Tötet Häuptling Nek'rosh.\n\nBringt Nek'roshs Kopf zu Captain Stoutfist.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[475] = { title = "Ein beunruhigender Wind", description = "Ein beunruhigender Wind weht durch den Wald.\n\nGaerolas Talvethren dient den schlafenden Druiden der Kralle in den Grabhügeln von Ban'ethil als Großer Aufseher. Seine Pflicht als auserwählter Beschützer der Schlafenden ist es, deren Sicherheit zu gewährleisten, auf dass sie ihrem Pakt mit Ysera gerecht werden.\n\nAber es gab länger keine Nachricht von Gaerolas, und ich werde etwas nervös. Reist nach Osten, zum Dorf Starbreeze, und bringt mir einen Bericht von Gaerolas, auf dass ich meine Sorgen begraben kann, da ich weiß, dass meine träumenden Brüder sicher schlummern.", objectives = "Sucht Gaerolas Talvethren im Dorf Starbreeze auf.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[476] = { title = "Die Verderbnis der Knarzklauen", description = "Der Knarzklauenstamm ist verderbt worden!\n\nDie einstmals friedliebenden Furbolgs haben sich gegen die Beschützer des Waldes gewandt. Sie haben mich hinterrücks überfallen, als ich auf dem Weg zum Grabhügel von Ban'ethil war und liefen weiter, um Starbreeze zu plündern. Ursal der Raufer, ihr Häuptling, benutzt die bösen Mächte des Teufelsmooses, um sie wahnsinnig werden zu lassen.\n\nMeine Wunden sind zu schwer, ich kann nicht zu Athridas zurückkehren und ihm diese schlimme Nachricht überbringen. Junger $C, diese Aufgabe bleibt Euch überlassen. Wir können nur hoffen, dass die verrückten Knarzklauen noch nicht bis nach Ban'ethil vorgedrungen sind!", objectives = "Kehrt zu Athridas Bearmantle nach Dolanaar zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[477] = { title = "Grenzübergänge", description = "Wie Ihr vielleicht bereits wisst, die Stadt Ambermill ist weiterhin eine Quelle der menschlichen Opposition, die nötige Unterstützung erhalten sie meist durch die Hexer von Dalaran.\n\nIch weiß nicht, wie ihr Plan aussieht, aber ihr Interesse an einem Hinterwäldler-Dorf wie Ambermill zeigt mir, dass es von größerer Bedeutung sein muss.\n\nVon Hillsbrad aus haben sie wagenweise Kisten geliefert. Viele dieser Vorräte werden in ein kleines Camp nördlich von Pyrewood gebracht. Bringt mir den Inhalt einer dieser Kisten.", objectives = "Holt den Inhalt einer der Kisten von den Hexern aus Dalaran. Ihr findet Pyrewood im Süden.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[478] = { title = "Karten und Runen", description = "<Schnell entnehmt Ihr den Anhänger aus der Kiste und setzt den Deckel wieder auf.>", objectives = "Bringt den seltsamen Anhänger zu Schattenpriester Allister in dem Grabmal.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[479] = { title = "Ambermill-Nachforschungen", description = "Dalar versucht die Quelle für die Zaubereien der Hexer zu finden. In der Zwischenzeit müssen wir ihren Fortschritt mit allen Mitteln aufhalten...\n\nAlle Herbeizauberer, Magier und Beschützer tragen mit Sicherheit ihre Anhänger. Nehmt sie ihnen ab und bringt sie hierher.\n\nFolgt der Hauptstraße in südlicher Richtung und nehmt dann die östliche Abzweigung nach Ambermill.", objectives = "Beschafft 8 Anhänger aus Dalaran für Schattenpriester Allister beim Grabmal.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[480] = { title = "Der Wirker", description = "Ein Erzmagier von großer Macht leitet die Reaktivierung des Leyenergieknotens. Angesichts ihres Fortschritts liegt unsere einzige Hoffnung, sie noch aufzuhalten, darin, ihn zu töten. Das ist eine schwierige Tat, denn ohne Zweifel wird er von anderen Magiern und Wärtern beschützt.\n\nIhr müsst ihn schnellstens erledigen. Bringt mir seinen Stab, sobald er tot ist. Geht jetzt.", objectives = "Tötet den Erzmagier von Dalaran und bringt seinen Stab zu Schattenpriester Allister in dem Grabmal.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[481] = { title = "Dalars Analyse", description = "Bringt den Anhänger zu Dalar Dawnweaver, vielleicht kann er Licht in das Dunkel der Hexerpläne bringen.", objectives = "Bringt den mit Runen gravierten Anhänger zu Dalar Dawnweaver in dem Grabmal.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[482] = { title = "Dalaran Absichten", description = "Natürlich! Wie konnte ich das vergessen?\n\nAmbermill war einer der Orte, die von den Kirin Tor gekennzeichnet wurden, weil dort ein ruhender Leyenergieknoten liegt. Mit Sicherheit haben die Hexer vor, diesen Knoten wiederzuerwecken und seine Energien für etwas Größeres zu nutzen.\n\nDas dürfen wir nicht zulassen...\n\nUm die Leyenergien des Gebietes zu aktivieren, bedarf es einer großen Macht. Wir können sie aufhalten, indem wir die Anhänger der Hexer an uns nehmen.\n\nBringt diese Information zu Allister, er wird dann über das weitere Vorgehen entscheiden.", objectives = "Sprecht mit dem Schattenpriester Allister in dem Grabmal.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[483] = { title = "Die Relikte des Erwachens", description = "Eindringlinge der Knarzklauen wurden beim Überfall im Westen des Ban'ethil-Grabhügels gesehen.\n\nWenn wir ihnen nicht zur Hilfe kommen, werden die schlummernden Druiden auf ewig im Smaragdgrünen Traum gefangen gehalten, vollkommen ahnungslos ihrem Schicksal ausgeliefert. Das empfindliche Ritual des Großen Schlafes kann ohne die Relikte des Erwachens nicht unterbrochen werden.\n\nReist zum Höhlenbau und bringt den Rabenkrallentalisman, den schwarzen Federkiel, den Saphir des Himmels sowie die Rune des Nistens herbei. Die Druiden bewahren sie in heiligen Truhen auf. Bringt sie zu mir, damit ich das Weck-Ritual vorbereiten kann.", objectives = "Bringt die Relikte des Erwachens zu Athridas Bearmantle nach Dolanaar.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[484] = { title = "Häute junger Krokilisken", description = "Ich bin James Halloran, der Gerber. Meine gegerbten Krokiliskenhäute sind nah und fern begehrt, Lieferungen gehen per Schiff zu allen Häfen der Welt.\n\nHabt Ihr Einar getroffen? Er ist einer der Jäger, die mir Krokiliskenhäute bringen.\n\nMir fehlen zurzeit weichere Häute, wie die von jungen Krokilisken.\n\nDa ich bald keine mehr habe, bin ich bereit, Euch einen Spitzenpreis für einen Stapel der Häute zu bezahlen. Ihr könnt die jungen Kroks in den Marschen gleich außerhalb der Stadt finden.", objectives = "Besorgt Euch 4 Häute junger Krokilisken für James Halloran im Hafen von Menethil.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[485] = { title = "Sucht OOX-09/HL!", description = "Ihr habt ein merkwürdiges Gerät aus Metall entdeckt, das die Form eines Eis hat. Als Ihr einen der Knöpfe berührt, erwacht das Ei zu Leben und verwandelt sich in eine Art Gnom-Roboter-Apparat! Aus dem Inneren des Roboteis erklingt eine rasselnde Stimme.\n\n\"Mein Name ist Oglethorpe Obnoticus und mein Leitroboter ist abgestürzt! Ich werde Euch belohnen, wenn Ihr ihn aufspürt. Bringt dem Roboter bitte diesen Signalgeber!\"\n\n\"Ich habe jetzt die Koordinaten des Roboters für Euch berechnet. Er ist in der Nähe von Skulk Rock abgestürzt, dort, wo der Fluss entspringt!\"", objectives = "Bringt das Notsignal zu Oglethorpes Leitroboter an der Quelle des Flusses im Hinterland, nahe Skulk Rock.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[486] = { title = "Ursal der Raufer", description = "Jetzt ist die Zeit gekommen, die Druiden der Kralle zu retten. $N, sollten wir jetzt versagen, sind sie für immer im Schlaf verloren.\n\nIch werde die Relikte des Erwachens vorbereiten und das Ritual durchführen. Damit meine Arbeit Wirkung zeigen kann, muss die verfluchte Bestie, die für diese schreckliche Situation verantwortlich ist, getötet werden. Erst dann ist das Ritual vollkommen.\n\nEs war Ursal der Raufer, der sich in die Berufung unserer Brüder eingemischt hat, und er ist es auch, der nun bezahlen muss, damit sie befreit werden können. Begebt Euch nach Südwesten zur Höhle der Knarzklauen und erschlagt ihn.", objectives = "Tötet Ursal den Raufer und kehrt zu Athridas Bearmantle nach Dolanaar zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[487] = { title = "Die Straße nach Darnassus", description = "Die Straße nach Darnassus muss sicher bleiben. Reisende, die von Dolanaar nach Darnassus fuhren, haben von ruchlosen Angriffen der verderbten Furbolgs des Knarzklauenstammes berichtet.\n\nJeden Tag gelangen auf diesem Weg wichtige Nachrichten und auch Waren von und nach Darnassus. Es darf einfach nicht sein, dass eine schurkische Bande von Heiden alle terrorisiert.\n\n$C, bewaffnet Euch im Namen des Heiligen Waldes. Ihr Bau liegt irgendwo unterhalb dieser Position. Erschlagt 6 Wegelagerer der Knarzklauen und berichtet mir dann.", objectives = "Erschlagt 6 Wegelagerer der Knarzklauen und kehrt zu Schildwache Amara Nightwalker außerhalb Dolanaars zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[488] = { title = "Zenns Aufträge", description = "Ihr seid bereit zu arbeiten, wie ich sehe. Ihr habt Glück, denn es vergeht kein Tag, an dem ich mir nicht wünschte, ein junger $C wäre hier, der mir zur Hand geht.\n\nIhr seht, $N , ich kann Euch zu Eurem Glück verhelfen und mit Dingen versorgen, von denen Ihr nie zu träumen wagtet. Damit dies jedoch geschieht, müsst Ihr mir gewisse Dinge beschaffen.\n\nMeine Angelegenheiten im Wald erfordern oft gewisse... Reagenzien. Bringt mir 3 Nachtsäbler-Fangzähne, 3 Strigideulenfedern und 3 Streifen Waldweberspinnenseide.\n\nDas soll unser kleines Geheimnis bleiben, $R.", objectives = "Bringt Zenn Foulhoof außerhalb von Dolanaar 3 Nachtsäblerfangzähne, 3 Strigideulenfedern und 3 Streifen Waldweberspinnenseide.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[489] = { title = "Sucht Befreiung!", description = "Der Rat des Waldes hat die Meldung erhalten, dass Ihr Zenn Foulhoof behilflich gewesen seid. Der Satyr ist ein Feind des Waldes. Als $R müsstet Ihr eigentlich mehr Verstand haben, als den Wald zu entweihen, indem Ihr Kreaturen der Natur tötet.\n\nIhr müsst Eure Ehre in den Augen des Rates wiederherstellen, wenn Ihr weiterhin ein Freund von Teldrassil bleiben wollt.\n\nErteilt Foulhoof eine Lektion, dann habt ihr Eure Schuld beglichen. Teufelszapfen sind verderbte Samen, die von Bäumen fallen. Sie sondern grünen Rauch ab.\n\nGebt Foulhoof einige davon. Er wird denken, dass Ihr ihm eine harmlose Leckerei gebracht habt.", objectives = "Sammelt 3 Teufelszapfen und gebt sie Zenn Foulhoof außerhalb von Dolanaar.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[491] = { title = "Zauberstab an Bethor", description = "Thule erzählte mir einmal, dass er und zwei Kollegen vor langer Zeit einen magischen Zauberstab herstellten, der aus den Lehrlingszauberstäben zusammengewoben wurde, den jeder Magier besaß. Dieser Zauberstab war ein Symbol ihrer Freundschaft, und obwohl Thule ihn hinterher verachtete, konnte er sich doch weder davon trennen noch ihn den anderen überlassen. Also stahl er den Zauberstab und versteckte ihn in Burg Fenris.\n\nHier. Bringt den Zauberstab zu Bethor Iceshard, einem Freund von Thule aus vergangenen Zeiten. Ich bin sicher, er möchte ihn haben.", objectives = "Bringt den gewebten Zauberstab zu Bethor Iceshard in das Magieviertel von Undercity.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[492] = { title = "Eine neue Seuche", description = "Berichten der Todeswachen zufolge wurde gerade ein weiterer dieser dummen Zwergen-Gebirgsjäger gefangen genommen. Die Todeswächter benutzen gern den Keller der Taverne Zur Galgenschlinge als Übergangszelle, bis man sich \"richtig\" um die Gefangenen kümmern kann.\n\nWarum... kümmert... Ihr Euch nicht um den gefangenen Gebirgsjäger und schaut, wie er das Spezialgetränk verträgt, das ich für ihn gemacht habe? Das ist nur ein kleiner Eindruck dessen, was die dunkle Fürstin für den Rest von Azeroth geplant hat.", objectives = "Bringt Johaans Spezialgetränk zum gefangenen Gebirgsjäger.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[493] = { title = "Reise in das Vorgebirge von Hillsbrad", description = "Die Königliche Apothekervereinigung steht unter enormem Druck seitens der dunklen Fürstin, eine neue Seuche zu entwickeln. Wir arbeiten sehr hart und haben bereits einige Fortschritte gemacht. Wir denken, dass der Erfolg sich umso schneller einstellen wird, wenn wir innerhalb der Vereinigung Informationen austauschen.\n\nAus diesem Grunde möchte ich, dass Ihr meine letzten Funde an Apotheker Lydon in Tarrens Mühle überbringt, einem kleinen Städtchen, das sich im Vorgebirge von Hillsbrad befindet. Die Reise wird sehr lange dauern.\n\nBegebt Euch Richtung Süden und bleibt auf den Straßen. Beachtet die Schilder auf das Genaueste!", objectives = "Bringt die Funde von Apotheker Renferrel zu Apotheker Lydon nach Tarrens Mühle im Vorgebirge von Hillsbrad.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[494] = { title = "Zeit zum Zuschlagen", description = "Schweigt und passt auf, $C.\n\nIch wurde an diesen Ort geschickt, um die Stadt Hillsbrad zu sondieren. Es handelt sich um eine Aufklärungsmission. Dabei ist von äußerster Wichtigkeit, dass Ihr sofort die Hochexekutorin Darthalia in Tarrens Mühle benachrichtigt. Bestellt ihr, ich, Todespirscherin Lesh, lasse ihr folgende Nachricht ausrichten:\n\n\"Der Schrei des Raben locket vom Westen her.\"\n\nFolgt der Straße gen Osten und beachtet die Schilder genau. Nun aber schnell! Macht Euch auf den Weg nach Tarrens Mühle. Es ist Eile geboten!", objectives = "Reist nach Tarrens Mühle, um die Nachricht von Todespirscherin Lesh an Hochexekutorin Darthalia zu überbringen.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[495] = { title = "Die Krone des Willens", description = "Mug'Thol und seine Ogerkriegsmeute wurde nach Alterac geschickt, um die Krone des Willens für Lady Sylvanas zu holen. Anstatt sie zurückzubringen, hat der Idiot allerdings versucht, sie aufzusetzen... Oger können wohl einfach keinen Dingen widerstehen, die glitzern und schimmern, nehme ich an.\n\nSeine stümperhaften Aktionen sind allerdings zu einem Problem geworden. Die Krone des Willens hat ihm geholfen, der Besessenheit zu widerstehen, die ihm auferlegt wurde, damit er Lady Sylvanas dient.\n\nDie dunkle Fürstin möchte ein Exempel statuieren. Begebt Euch nach Tarrens Mühle in Hillsbrad und meldet Euch bei Melisara, meinem dortigen Offizier.", objectives = "Meldet Euch bei Melisara in Tarrens Mühle im Vorgebirge von Hillsbrad.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[496] = { title = "Elixier des Leidens", description = "Ah, und wieder ein ekelhafter Tag in Tarrens Mühle. Diese ganze gesunde Luft verdirbt mir gründlich die Laune, $n.\n\nJe schneller wir die Menschen hier erkranken lassen können, desto besser. Ich habe intensive Studien über mögliche tödliche Zutaten für meine Gebräue durchgeführt, aber ich habe nicht die Zeit, sie alle zu sammeln.\n\nWenn Ihr Euch nützlich machen wollt, dann besorgt mir Folgendes: 10 Graubärzungen sowie das sehr seltene und schwer zu findende Krabblersekret. Bären und Krabbler könnt Ihr gleich außerhalb von Tarrens Mühle finden.", objectives = "Apotheker Lydon aus Tarrens Mühle möchte 10 Graubärzungen und etwas Krabblersekret.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[498] = { title = "Die Rettung", description = "Ich und einige andere Krieger wurden vom Kriegshäuptling geschickt, um ein Objekt aus Durnholde zu holen und dieses so genannte Syndikat zu untersuchen.\n\nAls wir nach Durnholde kamen, um uns umzusehen, wurden wir von einer großen Anzahl der Menschen überrascht. Wir haben mutig gekämpft, aber allein ihre Anzahl war so überwältigend groß, um uns zu besiegen. Sie haben einige von uns als Gefangene genommen, aber ich konnte entkommen.\n\nDurnholde befindet sich nicht weit südöstlich von uns, nur über den Fluss. Drull und Tog'thar werden dort gefangen gehalten, Ihr müsst sie retten.", objectives = "Krusk in Tarrens Mühle braucht Euch, um Drull und Tog'thar aus der Burg Durnholde zu befreien.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[499] = { title = "Elixier des Leidens", description = "Es wird einen Moment dauern, diese Komponenten zu vermengen, damit ein, wie ich es nenne, Elixier des Leidens entsteht.\n\nDann mal los! Ah, es gibt doch nichts Schöneres in diesem elendiglichen Vorgebirge, als ein wenig Leiden in die Welt zu bringen.\n\nLasst uns mal überprüfen, ob unser kleiner Trank auch seine gewünschte Wirkung hat.\n\nGebt meiner Assistentin Umpi einen kleinen Schluck von dem, was die Dunkle Fürstin sowohl für Menschen als auch für die Geißel geplant hat.", objectives = "Gebt Umpi das Elixier des Leidens", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[500] = { title = "Crushridge-Kopfgeld", description = "Die Crushridge-Oger haben einen Ogerhort im Alteracgebirge nahe der verfallenen Stadt Alterac gebaut. Meine Späher berichteten mir, dass sie auch die Ruinen da erobert haben.\n\nWir dürfen aber nicht zulassen, dass sie sich da fest einnisten. Falls sie sich dort zu sicher fühlen, werden sie bestimmt ins Vorgebirge eindringen und wären dann praktisch vor unserer Haustür!\n\nBegebt Euch nach Norden in das Alteracgebirge auf Ogerjagd. Bringt mir die schmutzigen Knöchelknochen, die sie tragen, und Ihr habt Euch ein hübsches Kopfgeld verdient.", objectives = "Sammelt 9 schmutzige Knöchelknochen von Crushridge-Ogern im Alteracgebirge. Bringt sie zu Marshal Redpath in Southshore.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[501] = { title = "Elixier der Schmerzen", description = "Oh, $N..., in Hillsbrad blühen die Blumen und die Luft ist so klar und rein. Ich muss in diesem ganzen Elend baden. Ich sehe aus meinem verdreckten Fenster und sehne den Tag herbei, an dem unsere neue Seuche dieser Welt ihren wohlverdienten Tod bringt.\n\nSo gern ich auch den ganzen Tag hier herumsitzen und mit Grübeln verbringen würde, meine Pflicht gegenüber der dunklen Fürstin ruft mich. Würdet Ihr mir helfen? Meine Forschungen führen mich zu der Annahme, dass sich aus Berglöwenblut ein vorzüglicher Todestrank herstellen lässt. Bringt mir etwas davon, dann können wir ein bisschen Spaß haben.", objectives = "Bringt 10 Phiolen mit Berglöwenblut zu Apotheker Lydon in Tarrens Mühle.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[502] = { title = "Elixier der Schmerzen", description = "Ah, es geht doch nichts über den Geruch von frischem Blut im Vorgebirge!\n\nDann lasst uns eine Prise davon und ein wenig hiervon vermischen - und der einzig wahre Spaß kann beginnen! Die Kreation aus diesem Blut möchte ich Elixier der Schmerzen nennen. Wenn meine Berechnungen korrekt sind, sollte dieses Gebräu der Anfang von etwas Wunderbarem für Lady Sylvanas sein. Aber wir müssen erst mal einen Testlauf machen.\n\nBringt dieses Elixier zum nördlichen Hof in den Feldern von Hillsbrad im Südwesten. Lasst uns sehen, wie Stanley, dem kleinen Hund von Bauer Ray, dieses 'Leckerli' so schmeckt.", objectives = "Füttert Stanley mit dem Elixier der Schmerzen.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[503] = { title = "Gol'dir", description = "Soweit ich das aus den Dokumenten, die Ihr herbrachtet, ersehen kann, wird Gol'dir in einem großen Syndikatsstützpunkt im Norden festgehalten, höchstwahrscheinlich im Alteracgebirge. Er ist schon zu lange dort gefangen und muss endlich befreit werden.", objectives = "Befreit Gol'dir und kehrt dann zu Krusk in Tarrens Mühle zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[504] = { title = "Crushridge-Kriegstreiber", description = "Nun, da Ihr die Bekanntschaft der Crushbridge-Oger gemacht habt, möchte ich, dass Ihr ihnen so richtig zeigt, was eine Harke ist...\n\nGeht zu den Ruinen von Alterac und sucht die Crushridge-Kriegstreiber. Ihr sollt eine große Anzahl von ihnen erschlagen - das ist der einzige Weg, um diese Schläger von dem Gebiet der Allianz fern zu halten.", objectives = "Erschlagt 15 Crushridge-Kriegstreiber und kehrt dann zu Marshal Redpath in Southshore zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[505] = { title = "Auftragsmörder des Syndikats", description = "Ich bin der neue Magistrat von Southshore. Ich wurde erst kürzlich ernannt, nachdem der vorherige Magistrat ermordet worden ist. Die Mörder wurden nie gefunden, aber unsere Nachforschungen haben ergeben, dass sie höchstwahrscheinlich vom Syndikat angeworben wurden - einer Gruppe von Dieben, angeführt von schurkischen Edlen des jetzt gefallenen Königsreichs von Alterac.\n\nDas Syndikat hat ein Lager nördlich von Tarrens Mühle, das von der Horde besetzt ist, und unsere neuesten Hinweise führen genau in dieses Lager. Erschlagt die Syndikatsmitglieder, die Ihr dort vorfindet.", objectives = "Tötet 12 Schleicher des Syndikats und 8 Diebe des Syndikats, kehrt dann zurück zu Magistrat Henry Maleb nach Southshore.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[506] = { title = "Blackmoores Vermächtnis", description = "Vor ein oder zwei Tagen erhielt ich Besuch vom Anführer dieses Syndikats. Sein Name war Aliden Perenolde und er nannte sich selbst Lord dieses Landes. Er vertraute mir seine Pläne an, die Orcs, die sich gegen ihn gewandt hatten, zu Sklaven zu machen, genau wie es einst auch sein Vater und Mentor, der geächtete Blackmoore, geplant hatte.\n\nAber viel wichtiger war, dass er seine Geliebte mitbrachte, ein zartes Mädchen namens Elysa. Um ihren Hals trug sie den Anhänger, den der Kriegshäuptling als sein Eigen wünscht.\n\nGeht jetzt, ich gehe meine eigenen Wege, nachdem ich meine Geschäfte hier erledigt habe.", objectives = "Bringt die von Gol'dir gesammelten Informationen zu Krusk in Tarrens Mühle.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[507] = { title = "Lord Aliden Perenolde", description = "Es ist unumstritten, dass Perenolde getötet werden und seine Verderbtheit ausgelöscht werden muss. Sein Herrenhaus liegt weit nördlich von hier, an den Ufern des Lordameresees. $n, tut Eure Pflicht, holt danach den Anhänger, den der Kriegshäuptling zu haben wünscht, und kehrt dann hierher zurück.", objectives = "Tötet Lord Aliden Perenolde und befragt seine Geliebte Elysa nach Tarethas Anhänger.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[508] = { title = "Tarethas Geschenk", description = "Den Anhänger? Aber natürlich könnt Ihr ihn haben... Nehmt ihn! Nichts soll mich an ihn erinnern... nur bitte geht, bitte geht in Frieden...", objectives = "Bringt Tarethas Anhänger zu Krusk nach Tarrens Mühle.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[509] = { title = "Elixier der Pein", description = "Ein neuer Tag, ein neues Elixier. Wenn ich was zu sagen hätte, würde ich diese lächerlichen Menschen und die Geißel die Sache einfach unter sich ausmachen lassen. Sie scheinen ohnehin absolut darauf versessen zu sein, sich gegenseitig umzubringen.\n\nAber leider hat es sich unsere dunkle Fürstin in den Kopf gesetzt, das Ganze ein wenig zu beschleunigen. Also warum diese düsteren Tage nicht dazu nutzen und hier ein wenig Tod und Krankheit verbreiten?\n\n$N, das ist mein Plan: Ihr macht Euch auf den Weg zur Nethander-Siedlung. Das ist südlich von Tarrens Mühle und östlich des Flusses und Southshore. Sammelt in den Feldern dort 6 Morastschnauzenkappen für mein nächstes Elixier.", objectives = "Bringt 6 Morastschnauzenkappen zu Apotheker Lydon in Tarrens Mühle.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[510] = { title = "Furchteinflößende Pläne", description = "Unter diesen Dokumenten befindet sich eine Liste der benötigten Vorräte. Das sind unter anderem ganz banale Dinge (Nahrung, Waffen, Kleidung) wie auch etwas exotischere Ausrüstungsgegenstände (Masken, Öl, Gift).\n\nAber am auffälligsten ist die Dringlichkeit dieses Auftrags - diese Vorräte werden schnellstens benötigt, um eine Unternehmung zu starten, die in dem Dokument als 'wichtige Mission gegen Southshore' beschrieben wird.", objectives = "Bringt die furchteinflößenden Pläne zu Magistrat Henry Maleb nach Southshore.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[511] = { title = "Verschlüsselter Brief", description = "Einer der Briefe auf diesem Tisch ist verschlüsselt und nicht zu ergründen.", objectives = "Bringt den verschlüsselten Brief zum Meister der Lehren Dibbs nach Southshore.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[512] = { title = "Tod der Edlen", description = "Ich fürchte, die Führung, die hinter dem Syndikat steht, will Southshore unbedingt ruinieren. Wir müssen diese Anführer mit aller Kraft schlagen, bevor sie ihre Pläne in die Tat umsetzen können.\n\nGeht zu den Ruinen von Strahnbrad, im Alteracgebirge im Norden. Wir glauben, dass das Syndikat dieses Gebiet als Hauptquartier benutzt.\n\nWir wissen, dass diese Bande von Halsabschneidern von ehemaligen Adligen von Alterac angeführt wird. Sie mögen sich als normale Agenten des Syndikats verkleiden, aber wenn Ihr sie tötet, werdet Ihr einen Edlen an dem Siegelring erkennen, den er trägt.\n\nBringt mir diese Siegelringe.", objectives = "Bringt 7 Alteracsiegelringe zu Magistrat Henry Maleb nach Southshore.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[513] = { title = "Elixier der Pein", description = "Gerade dachte ich noch, ein weiterer Tag ohne jegliches Amüsement, und da kommt Ihr und bringt diese wunderbaren Morastschnauzenkappen.\n\nZuerst werde ich sie zu einem feinen Gemisch zusammenrühren. Dann werden wir Meisterapotheker Faranell in Undercity benötigen, damit er seine Paste des Verfalls hinzufügt, und dann geht der Spaß erst richtig los!\n\nHier, $N, nehmt dieses Morastschnauzengemisch und bringt es schnell zu Meister Faranell.", objectives = "Bringt das Morastschnauzengemisch zu Meisterapotheker Faranell in Undercity.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[514] = { title = "Brief an Stormpike", description = "Ich habe einen Kollegen in Ironforge, der bei der Entschlüsselung dieses Briefes behilflich sein kann. Begebt Euch zur Bibliothek in der Halle der Forscher in Ironforge und sprecht mit Ausgrabungsleiter Stormpike. Richtet ihm aus, dass ich Euch geschickt habe, und zeigt ihm diesen Brief. Wenn es jemanden nördlich der Blackrockspitze gibt, der das hier lesen kann, dann ist er das.", objectives = "Bringt den geschickt verschlüsselten Brief zu Ausgrabungsleiter Stormpike nach Ironforge.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[515] = { title = "Elixier der Pein", description = "Ein Morastschnauzengemisch? Das ist wirklich brillant! Warum ist mir das nicht eingefallen?\n\nLasst mich meine Paste des Verfalls diesem Teufelsgebräu hinzufügen.\n\nDamit die verunreinigenden Agenzien in dieser Morastschnauzenmixtur aktiviert werden, benötigt Lydon starken Trollbluttrank, sowie einige Säbelflossenschuppen und Fetzenflossenaugen von der Südküste Hillsbrads. Er wird wissen, was zu tun ist, sobald Ihr alle Reagenzien zusammengetragen habt. Ich kann es kaum abwarten zu erfahren, wie sein Experiment ablaufen wird!", objectives = "Bringt die Morastschnauzenmixtur, einen starken Trollbluttrank, 5 Säbelflossenschuppen und 5 Fetzenflossenaugen zu Apotheker Lydon nach Tarrens Mühle.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[516] = { title = "Berens List", description = "Ich habe Berichte erhalten, dass eine Gruppe Untoter sich zusammenrottet, um einen Angriff gegen uns vorzubereiten. Mit diesen Informationen können wir den Spieß umdrehen und sie zuerst angreifen, damit wäre ihr Plan erledigt.\n\nLeider sind meine Informationen gelinde gesagt unvollständig. Laut Bericht verstecken sie sich an einem Ort, der als Beren's Peril bekannt ist. Ihr genauer Standort ist unbekannt, aber es scheint eine Höhle in den Hügeln zu sein, nahe einem Nest der Hexer von Dalaran.\n\nIch vertraue auf Euren Einfallsreichtum. Findet sie und macht alles dem Erdboden gleich.", objectives = "Findet zuerst Beren's Peril, tötet 6 Zwangsarbeiter von Rabenklaue sowie 6 Wächter von Rabenklaue und kehrt dann zu Schattenpriester Allister in das Grabmal zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[517] = { title = "Elixier der Pein", description = "Das neue Elixier ist endlich bereit für einen Test. Aber warum solch eine vollkommene, höchst ansteckende Seuche an einen einfachen Frosch oder Hund verschwenden? Wir sollten uns in Lady Sylvanas Namen eine kleine Freude erlauben.\n\nGeht nach Dun Garok. Ihr kennt doch die Kasernen, in denen diese widerlichen kleinen Zwerge umhersausen. Ihr stehlt ein Fässchen Shindigger-Starkbier für mich. Sobald ich dieses Fässchen habe, können wir beide, Ihr und ich, eine kleine Party feiern, $N.", objectives = "Bringt ein Fässchen mit Shindigger-Starkbier zu Apotheker Lydon nach Tarrens Mühle.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[518] = { title = "Die Krone des Willens", description = "Mug'Thol und seine Crushridge-Oger haben die Ruinen von Alterac überrannt. Ihm eine schwere Strafe zukommen zu lassen, ohne die Anzahl der Oger zu verringern, wird nicht einfach sein.\n\nWir machen sie erst weich und sehen dann weiter.\n\nVerstanden? Gut. Dann geht.", objectives = "Tötet 14 Crushridge-Raufer für Melisara in Tarrens Mühle.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[519] = { title = "Die Krone des Willens", description = "Targ, Muckrake und Glommus sind Mug’Thols Offiziere. Sie sind ihm loyal ergeben, aber wer weiß schon, was einen Oger loyal sein lässt.\n\nBringt mir ihre Köpfe, $n, und dann muss nur noch Mug'Thols Kopf, mitsamt Krone, rollen.", objectives = "Tötet Targ, Muckrake und Glommus und bringt ihre Köpfe zu Melisara nach Tarrens Mühle.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[520] = { title = "Die Krone des Willens", description = "Nun, da Mug'Thols Offiziere tot sind, muss nur noch Mug'Thol selbst getötet und die Krone des Willens wieder zurückgebracht werden. Ich bin mir ziemlich sicher, dass er sie nur äußerst unwillig wieder hergeben wird. Außerdem wird er Euch wahrscheinlich bereits erwarten, in Anbetracht des... Ablebens... seiner Kumpanen.\n\nFindet Mug'Thol und bringt mir seinen Kopf und die Krone. Der Crushridge-Widerstand wird damit beendet sein.", objectives = "Tötet Mug'Thol und bringt seinen Kopf mit der Krone des Willens zu Melisara nach Tarrens Mühle.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[521] = { title = "Die Krone des Willens", description = "Es bleibt nur noch, die Krone des Willens zu Sharlindra nach Undercity zu bringen. Sie wird dafür sorgen, dass sie an Lady Sylvanas weitergeleitet wird. Ich warne Euch, auch nur daran zu denken, sie für Eure eigenen Zwecke zu verwenden, $N, Mug'Thols Schicksal sollte Beispiel genug sein.", objectives = "Bringt die Krone des Willens zu Sharlindra in Undercity.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[522] = { title = "Auftragsmördervertrag", description = "Dies ist ein Vertrag für die Ermordung des Magistrats Henry Maleb. Er wurde mit einem unverwechselbaren Siegelring in rotem Wachs gestempelt und versiegelt.", objectives = "Bringt den Auftragsmörder-Vertrag zu Magistrat Maleb nach Southshore.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[523] = { title = "Ableben des Barons", description = "Der Vertrag, den Ihr gebracht habt, wurde von Baron Vardus unterschrieben, einem Edlen aus dem ehemaligen Königreich von Alterac, und jemand der bekannt ist für seine Kaltherzigkeit und brutale Vorgehensweisen. Es überrascht mich nicht, dass jemand wie der Baron dahinter steckt.\n\nFindet diesen Mann. Findet ihn und führt ihn seiner gerechten Strafe zu. Er befindet sich sicherlich irgendwo in den Schlupfwinkeln des Syndikats - vielleicht in den Ruinen von Strahnbrad oder irgendwo in dem Tal im Norden davon.", objectives = "Bringt den Kopf von Baron Vardus zu Magistrat Maleb nach Southshore.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[524] = { title = "Elixier der Pein", description = "Nebenan halten die Todeswachen einige Bauern als Geiseln gefangen. Hochexekutorin Darthalia hatte vermutet, dass sich einer der Militärstrategen aus Stormwind unter ihnen versteckte. Anscheinend wurde dieser Militärstratege gestern Nacht tot in den Pestländern gefunden. Darthalia denkt ja immer so nett an mich und hat entschieden, dass die Gefangenen mir zu überlassen sind.\n\nIch denke, es ist höchste Zeit, dass wir für diese Bauern eine kleine Party schmeißen. Hört sich doch nach einer tollen Zeit an!\n\nStellt dieses besudelte Fässchen auf den Teppich in ihrem Zimmer. Seuchenbräu für alle!", objectives = "Stellt das besudelte Fässchen auf den Teppich für die gefangenen Bauern.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[525] = { title = "Weitere Geheimnisse", description = "Ich habe den Brief dechiffriert, aber ich weiß nicht, was ich davon halten soll. Ihr habt ihn unter Dieben im Vorgebirge von Alterac gefunden? Sehr seltsam...\n\nIhr solltet ihn zum Magistrat nach Southshore bringen. Auch wenn dieser Brief geheimnisvoll klingt, seine Stadt liegt Alterac am nächsten, wenn eine Bedrohung sich zusammenbraut, dann sollte gerade er davon erfahren.", objectives = "Bringt den entschlüsselten Brief zu Magistrat Maleb nach Southshore.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[526] = { title = "Lichtschmiedeblöcke", description = "Ihr mögt zwar einen Lichtschmiedeblock in dieser Truhe gefunden haben, aber das reicht nicht aus, um irgendetwas von Nutzen daraus zu schmieden.\n\nIhr solltet zurückgehen und nach weiteren suchen. Vielleicht tragen die Murlocs in der Nähe des Schiffswracks Lichtschmiedeblöcke mit sich herum.", objectives = "Sammelt 5 Lichtschmiedeblöcke und kehrt dann zu Glorin Steelbrow im Sumpfland zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
